window.PAGES = window.PAGES || {};
window.PAGES["day11-theory"] = {"title": "OCI Complete Revision, Skill Check & Certification Prep \u2014 Day 11 | Interactive Learning Platform", "css": "\n/* ============================================================\n   DESIGN TOKENS\n   Palette: void black base, Oracle red signal, cool blue for\n   network/data concepts, amber for warnings/exam-tips.\n   Type: Space Grotesk-style geometric display (system stack),\n   Inter-style body (system stack), JetBrains-style mono for\n   code/terminal (system stack) \u2014 no external fonts/CDNs.\n   ============================================================ */\n:host{\n  --void:#08090b;\n  --panel:#101217;\n  --panel-2:#15171e;\n  --panel-glass: rgba(21,23,30,0.6);\n  --border: rgba(255,255,255,0.08);\n  --border-strong: rgba(255,255,255,0.16);\n  --text-1:#eef0f3;\n  --text-2:#a7acb8;\n  --text-3:#6b7180;\n  --red:#c74634;\n  --red-bright:#ff5a3c;\n  --red-dim: rgba(199,70,52,0.15);\n  --blue:#4f8cff;\n  --blue-dim: rgba(79,140,255,0.15);\n  --amber:#e8a33d;\n  --amber-dim: rgba(232,163,61,0.15);\n  --green:#3ec28f;\n  --green-dim: rgba(62,194,143,0.15);\n  --radius: 14px;\n  --radius-sm: 8px;\n  --font-display: \"Space Grotesk\",\"Avenir Next\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;\n  --font-body: \"Inter\",\"Avenir Next\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;\n  --font-mono: \"JetBrains Mono\",\"SF Mono\",Consolas,\"Liberation Mono\",monospace;\n  --shadow-lg: 0 20px 60px rgba(0,0,0,0.5);\n  --shadow-sm: 0 4px 16px rgba(0,0,0,0.35);\n}\n:host([data-theme=\"light\"]){\n  --void:#f3f2ee;\n  --panel:#ffffff;\n  --panel-2:#f7f6f2;\n  --panel-glass: rgba(255,255,255,0.7);\n  --border: rgba(10,10,10,0.08);\n  --border-strong: rgba(10,10,10,0.16);\n  --text-1:#15171c;\n  --text-2:#4b4f58;\n  --text-3:#83879160;\n  --shadow-lg: 0 20px 60px rgba(0,0,0,0.12);\n  --shadow-sm: 0 4px 16px rgba(0,0,0,0.08);\n}\n*{box-sizing:border-box; margin:0; padding:0;}\n@media (prefers-reduced-motion: reduce){\n  *{animation-duration:0.001ms !important; animation-iteration-count:1 !important; transition-duration:0.001ms !important;}\n}\n:host{scroll-behavior:smooth;}\n:host{\n  background:var(--void);\n  color:var(--text-1);\n  font-family:var(--font-body);\n  line-height:1.6;\n  -webkit-font-smoothing:antialiased;\n  overflow-x:hidden;\n  transition:background .4s ease,color .4s ease;\n}\nbody::before{\n  content:\"\";\n  position:fixed; inset:0; z-index:0; pointer-events:none;\n  background:\n    radial-gradient(ellipse 800px 500px at 15% -5%, rgba(199,70,52,0.16), transparent 60%),\n    radial-gradient(ellipse 700px 500px at 100% 20%, rgba(79,140,255,0.10), transparent 60%),\n    radial-gradient(ellipse 600px 400px at 50% 100%, rgba(199,70,52,0.08), transparent 60%);\n}\nh1,h2,h3,h4{font-family:var(--font-display); letter-spacing:-0.02em; font-weight:700; color:var(--text-1);}\ncode, .mono{font-family:var(--font-mono);}\na{color:inherit;}\n::selection{background:var(--red); color:#fff;}\n::-webkit-scrollbar{width:10px; height:10px;}\n::-webkit-scrollbar-track{background:transparent;}\n::-webkit-scrollbar-thumb{background:var(--border-strong); border-radius:10px;}\n\n/* ---------- particles / ambient bg ---------- */\n#particles{position:fixed; inset:0; z-index:0; pointer-events:none; opacity:.5;}\n\n/* ---------- progress bar ---------- */\n#progress-bar{\n  position:fixed; top:0; left:0; height:3px; width:0%;\n  background:linear-gradient(90deg,var(--red),var(--red-bright));\n  z-index:9999; box-shadow:0 0 12px var(--red-bright);\n  transition:width .1s linear;\n}\n\n/* ---------- top bar ---------- */\n#topbar{\n  position:fixed; top:0; left:0; right:0; z-index:900;\n  height:60px; display:flex; align-items:center; gap:14px;\n  padding:0 18px; margin-top:3px;\n  background:var(--panel-glass); backdrop-filter:blur(16px) saturate(140%);\n  border-bottom:1px solid var(--border);\n}\n#topbar .brand{display:flex; align-items:center; gap:10px; font-family:var(--font-display); font-weight:700; font-size:15px; white-space:nowrap;}\n#topbar .brand .dot{width:10px; height:10px; border-radius:3px; background:linear-gradient(135deg,var(--red),var(--red-bright)); box-shadow:0 0 14px var(--red-bright);}\n#sidebar-toggle{\n  background:transparent; border:1px solid var(--border); color:var(--text-2);\n  width:36px; height:36px; border-radius:var(--radius-sm); cursor:pointer; font-size:16px;\n  display:flex; align-items:center; justify-content:center; transition:.2s;\n}\n#sidebar-toggle:hover{border-color:var(--border-strong); color:var(--text-1);}\n#search-wrap{position:relative; flex:1; max-width:420px;}\n#search{\n  width:100%; background:var(--panel); border:1px solid var(--border); color:var(--text-1);\n  padding:8px 14px 8px 34px; border-radius:999px; font-size:13px; font-family:var(--font-body);\n  outline:none; transition:.2s;\n}\n#search:focus{border-color:var(--red); box-shadow:0 0 0 3px var(--red-dim);}\n#search-wrap svg{position:absolute; left:12px; top:50%; transform:translateY(-50%); width:14px; height:14px; color:var(--text-3);}\n#search-results{\n  position:absolute; top:calc(100% + 8px); left:0; right:0; background:var(--panel);\n  border:1px solid var(--border-strong); border-radius:var(--radius-sm); box-shadow:var(--shadow-lg);\n  max-height:320px; overflow-y:auto; display:none; z-index:50;\n}\n#search-results a{display:block; padding:9px 14px; font-size:13px; color:var(--text-2); border-bottom:1px solid var(--border);}\n#search-results a:hover{background:var(--panel-2); color:var(--text-1);}\n#search-results .sr-cat{font-size:10px; text-transform:uppercase; letter-spacing:.08em; color:var(--red-bright); display:block; margin-bottom:2px;}\n\n.topbar-spacer{flex:1;}\n#theme-toggle{\n  background:var(--panel); border:1px solid var(--border); color:var(--text-2);\n  width:36px; height:36px; border-radius:999px; cursor:pointer; display:flex; align-items:center; justify-content:center;\n  transition:.2s; font-size:15px;\n}\n#theme-toggle:hover{border-color:var(--red); color:var(--red-bright);}\n#score-chip{\n  display:flex; align-items:center; gap:6px; background:var(--panel); border:1px solid var(--border);\n  padding:6px 12px; border-radius:999px; font-size:12px; color:var(--text-2); white-space:nowrap;\n}\n#score-chip b{color:var(--red-bright); font-family:var(--font-display);}\n\n/* ---------- layout ---------- */\n#shell{display:flex; padding-top:63px; position:relative; z-index:1;}\n#sidebar{\n  width:270px; flex-shrink:0; height:calc(100% - 63px); position:sticky; top:63px;\n  overflow-y:auto; border-right:1px solid var(--border); padding:18px 10px 60px;\n  transition:margin-left .3s ease, opacity .3s ease;\n}\n#sidebar.collapsed{margin-left:-270px; opacity:0;}\n#sidebar .nav-group{margin-bottom:4px;}\n#sidebar .nav-head{\n  font-size:10px; text-transform:uppercase; letter-spacing:.1em; color:var(--text-3);\n  padding:14px 12px 6px; font-weight:700;\n}\n#sidebar a.nav-link{\n  display:flex; align-items:center; gap:9px; padding:8px 12px; border-radius:var(--radius-sm);\n  font-size:13.5px; color:var(--text-2); text-decoration:none; transition:.15s; border-left:2px solid transparent;\n}\n#sidebar a.nav-link:hover{background:var(--panel); color:var(--text-1);}\n#sidebar a.nav-link.active{background:var(--red-dim); color:var(--red-bright); border-left-color:var(--red-bright); font-weight:600;}\n#sidebar a.nav-link .num{font-family:var(--font-mono); font-size:10px; color:var(--text-3); width:18px;}\n\nmain{flex:1; min-width:0; padding:0 0 100px;}\n.container{max-width:980px; margin:0 auto; padding:0 32px;}\n\n/* ---------- hero ---------- */\n#hero{position:relative; padding:100px 32px 70px; overflow:hidden; text-align:left;}\n#hero .eyebrow{\n  display:inline-flex; align-items:center; gap:8px; font-size:12px; letter-spacing:.1em; text-transform:uppercase;\n  color:var(--red-bright); background:var(--red-dim); border:1px solid rgba(199,70,52,0.3);\n  padding:6px 14px; border-radius:999px; margin-bottom:22px; font-weight:600;\n}\n#hero h1{font-size:clamp(2.4rem,5vw,4.2rem); line-height:1.02; max-width:820px;}\n#hero h1 .accent{background:linear-gradient(135deg,var(--red),var(--red-bright)); -webkit-background-clip:text; background-clip:text; color:transparent;}\n#hero p.lede{max-width:620px; font-size:17px; color:var(--text-2); margin-top:22px;}\n#hero .hero-stats{display:flex; gap:34px; margin-top:40px; flex-wrap:wrap;}\n#hero .hstat b{font-family:var(--font-display); font-size:26px; display:block;}\n#hero .hstat span{font-size:12px; color:var(--text-3); text-transform:uppercase; letter-spacing:.06em;}\n#hero .cta-row{display:flex; gap:14px; margin-top:38px; flex-wrap:wrap;}\n.btn{\n  font-family:var(--font-body); font-weight:600; font-size:14px; padding:12px 22px; border-radius:999px;\n  border:1px solid var(--border-strong); cursor:pointer; transition:.2s; display:inline-flex; align-items:center; gap:8px;\n}\n.btn-primary{background:linear-gradient(135deg,var(--red),var(--red-bright)); color:#fff; border:none; box-shadow:0 8px 24px rgba(199,70,52,0.35);}\n.btn-primary:hover{transform:translateY(-2px); box-shadow:0 12px 30px rgba(199,70,52,0.45);}\n.btn-ghost{background:var(--panel); color:var(--text-1);}\n.btn-ghost:hover{border-color:var(--red); color:var(--red-bright);}\n\n/* orbiting node animation in hero */\n#hero-orbit{position:absolute; right:-60px; top:40px; width:420px; height:420px; opacity:.9; pointer-events:none;}\n@media (max-width:1100px){#hero-orbit{display:none;}}\n\n/* ---------- sections ---------- */\nsection.chapter{padding:70px 0 10px; border-top:1px solid var(--border); scroll-margin-top:80px;}\nsection.chapter:first-of-type{border-top:none;}\n.chapter-kicker{display:flex; align-items:center; gap:10px; margin-bottom:14px;}\n.chapter-kicker .idx{\n  font-family:var(--font-mono); font-size:12px; color:var(--red-bright); background:var(--red-dim);\n  padding:4px 10px; border-radius:6px; border:1px solid rgba(199,70,52,.3);\n}\n.chapter-kicker .track{font-size:11px; text-transform:uppercase; letter-spacing:.1em; color:var(--text-3);}\n.chapter h2{font-size:clamp(1.6rem,3vw,2.3rem); margin-bottom:6px;}\n.chapter .dek{color:var(--text-2); font-size:15.5px; max-width:680px; margin-bottom:30px;}\n.chapter h3{font-size:1.15rem; margin:34px 0 14px;}\n.chapter p{color:var(--text-2); font-size:15px; margin-bottom:14px; max-width:720px;}\n.chapter ul, .chapter ol{color:var(--text-2); font-size:15px; margin:0 0 16px 20px;}\n.chapter li{margin-bottom:6px;}\n.chapter strong{color:var(--text-1);}\n\n/* scroll reveal */\n.reveal{opacity:0; transform:translateY(24px); transition:opacity .7s ease, transform .7s ease;}\n.reveal.in{opacity:1; transform:translateY(0);}\n\n/* ---------- cards / panels ---------- */\n.panel{\n  background:linear-gradient(180deg,var(--panel),var(--panel-2));\n  border:1px solid var(--border); border-radius:var(--radius); padding:24px;\n  box-shadow:var(--shadow-sm); position:relative;\n}\n.panel-glow{position:relative; overflow:hidden;}\n.panel-glow::before{\n  content:\"\"; position:absolute; inset:-2px; z-index:-1; border-radius:inherit;\n  background:conic-gradient(from 180deg, var(--red), transparent 30%, var(--blue), transparent 70%, var(--red));\n  opacity:0; transition:opacity .4s;\n}\n.panel-glow:hover::before{opacity:.5;}\n.panel-glow > .panel-inner{background:var(--panel); border-radius:calc(var(--radius) - 1px); height:100%; padding:22px;}\n\n.grid{display:grid; gap:16px;}\n.grid-2{grid-template-columns:1fr 1fr;}\n.grid-3{grid-template-columns:repeat(3,1fr);}\n.grid-4{grid-template-columns:repeat(4,1fr);}\n@media (max-width:800px){.grid-2,.grid-3,.grid-4{grid-template-columns:1fr;}}\n\n.card{\n  background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm);\n  padding:18px; transition:.25s; cursor:default;\n}\n.card:hover{border-color:var(--border-strong); transform:translateY(-3px); box-shadow:var(--shadow-sm);}\n.card h4{font-size:14px; margin-bottom:8px; display:flex; align-items:center; gap:8px;}\n.card p{font-size:13.5px; margin:0; color:var(--text-2);}\n.card .tag{font-size:10px; text-transform:uppercase; letter-spacing:.06em; color:var(--red-bright); background:var(--red-dim); padding:3px 8px; border-radius:6px; margin-bottom:8px; display:inline-block;}\n\n/* ---------- callouts ---------- */\n.callout{border-radius:var(--radius-sm); padding:14px 16px; margin:16px 0; border:1px solid; font-size:14px; display:flex; gap:12px; align-items:flex-start;}\n.callout .ic{font-size:16px; flex-shrink:0; margin-top:1px;}\n.callout-tip{background:var(--green-dim); border-color:rgba(62,194,143,.35); color:var(--text-1);}\n.callout-warn{background:var(--amber-dim); border-color:rgba(232,163,61,.35); color:var(--text-1);}\n.callout-trap{background:var(--red-dim); border-color:rgba(199,70,52,.35); color:var(--text-1);}\n.callout-q{background:var(--blue-dim); border-color:rgba(79,140,255,.35); color:var(--text-1);}\n.callout b{display:block; font-size:11px; text-transform:uppercase; letter-spacing:.06em; margin-bottom:3px;}\n\n/* ---------- tables ---------- */\ntable.cmp{width:100%; border-collapse:collapse; font-size:13.5px; margin:18px 0;}\ntable.cmp th{text-align:left; color:var(--text-3); font-size:11px; text-transform:uppercase; letter-spacing:.06em; padding:10px 12px; border-bottom:1px solid var(--border-strong);}\ntable.cmp td{padding:12px; border-bottom:1px solid var(--border); color:var(--text-2);}\ntable.cmp tr:hover td{background:var(--panel);}\ntable.cmp td:first-child, table.cmp th:first-child{color:var(--text-1); font-weight:600;}\n\n/* ---------- buttons small ---------- */\n.chip-btn{\n  background:var(--panel-2); border:1px solid var(--border); color:var(--text-2); font-size:12.5px;\n  padding:7px 14px; border-radius:999px; cursor:pointer; transition:.2s; font-family:var(--font-body); font-weight:600;\n}\n.chip-btn:hover{border-color:var(--red); color:var(--red-bright);}\n.chip-btn.active{background:var(--red); color:#fff; border-color:var(--red);}\n.chip-btn:disabled{opacity:.4; cursor:not-allowed;}\n\n/* end of part1 */\n\n\n.vm-sim{display:grid; grid-template-columns:280px 1fr; gap:20px;}\n@media (max-width:800px){.vm-sim{grid-template-columns:1fr;}}\n.vm-controls{display:flex; flex-direction:column; gap:10px;}\n.vm-controls label{font-size:11px; text-transform:uppercase; letter-spacing:.06em; color:var(--text-3); margin-top:6px;}\n.vm-controls input[type=range]{width:100%; accent-color:var(--red);}\n.host-box{border:1px dashed var(--border-strong); border-radius:var(--radius-sm); padding:16px; position:relative; background:repeating-linear-gradient(135deg, rgba(255,255,255,0.015) 0 10px, transparent 10px 20px);}\n.host-meter{display:flex; justify-content:space-between; font-size:11px; color:var(--text-3); margin-bottom:6px;}\n.meter-bar{height:8px; border-radius:6px; background:var(--panel-2); overflow:hidden; margin-bottom:14px;}\n.meter-fill{height:100%; border-radius:6px; transition:width .4s ease; background:linear-gradient(90deg,var(--blue),#7db2ff);}\n.meter-fill.cpu{background:linear-gradient(90deg,var(--red),var(--red-bright));}\n.vm-list{display:flex; flex-wrap:wrap; gap:10px; min-height:60px;}\n.vm-card{width:110px; background:var(--panel); border:1px solid var(--border-strong); border-radius:10px; padding:10px; font-size:11px; animation:popIn .3s ease; position:relative;}\n.vm-card .vm-name{font-family:var(--font-mono); color:var(--blue); font-weight:700; margin-bottom:4px;}\n.vm-card .vm-x{position:absolute; top:6px; right:8px; cursor:pointer; color:var(--text-3);}\n.vm-card .vm-x:hover{color:var(--red-bright);}\n@keyframes popIn{from{opacity:0; transform:scale(.7);} to{opacity:1; transform:scale(1);}}\n.layer-stack{display:flex; flex-direction:column; gap:6px;}\n.layer-row{display:grid; grid-template-columns:130px 1fr; gap:0; border-radius:var(--radius-sm); overflow:hidden; border:1px solid var(--border);}\n.layer-label{background:var(--panel-2); display:flex; align-items:center; justify-content:center; font-family:var(--font-display); font-weight:700; font-size:13px;}\n.layer-cells{display:grid; grid-template-columns:repeat(6,1fr);}\n.layer-cell{padding:12px 6px; text-align:center; font-size:11px; border-left:1px solid var(--border); transition:.2s; cursor:default;}\n.layer-cell.you{background:var(--red-dim); color:var(--red-bright); font-weight:700;}\n.layer-cell.oracle{background:var(--blue-dim); color:var(--blue); font-weight:700;}\n.layer-cell:hover{filter:brightness(1.3);}\n.layer-legend{display:flex; gap:18px; margin-top:12px; font-size:12px; color:var(--text-2);}\n.legend-dot{width:10px; height:10px; border-radius:3px; display:inline-block; margin-right:6px; vertical-align:-1px;}\n.resp-track{position:relative; height:10px; border-radius:6px; background:linear-gradient(90deg,var(--blue) 0%,var(--blue) var(--split,50%), var(--red) var(--split,50%), var(--red) 100%); margin:30px 0 10px;}\n.resp-handle{position:absolute; top:50%; left:var(--split,50%); transform:translate(-50%,-50%); width:26px; height:26px; border-radius:50%; background:#fff; border:3px solid var(--void); cursor:grab; box-shadow:0 0 0 4px rgba(255,255,255,0.15);}\n.resp-labels{display:flex; justify-content:space-between; font-size:12px; color:var(--text-2); margin-bottom:4px;}\n.resp-layers{display:flex; flex-direction:column; gap:8px; margin-top:20px;}\n.resp-layer-row{display:flex; align-items:center; gap:12px; font-size:13px;}\n.resp-layer-row .name{width:150px; flex-shrink:0; color:var(--text-1); font-weight:600;}\n.resp-layer-row .who{font-family:var(--font-mono); font-size:11px; padding:4px 10px; border-radius:6px;}\n.who-oracle{background:var(--blue-dim); color:var(--blue);}\n.who-you{background:var(--red-dim); color:var(--red-bright);}\n.who-shared{background:var(--amber-dim); color:var(--amber);}\n.map-wrap{display:grid; grid-template-columns:1fr 260px; gap:20px;}\n@media (max-width:800px){.map-wrap{grid-template-columns:1fr;}}\n.region-dot{cursor:pointer; transition:.2s;}\n.region-dot circle{transition:.2s;}\n.region-info{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:16px; font-size:13px; min-height:180px;}\n.region-info h4{font-size:14px; color:var(--red-bright); margin-bottom:8px;}\n.region-info .placeholder{color:var(--text-3); font-style:italic;}\n.ad-buildings{display:flex; gap:16px; justify-content:center; margin:20px 0; flex-wrap:wrap;}\n.building{width:120px; text-align:center; padding:16px 10px; border-radius:var(--radius-sm); border:1px solid var(--border-strong); background:var(--panel); transition:.4s;}\n.building .roof{font-size:26px; margin-bottom:6px;}\n.building .b-name{font-family:var(--font-mono); font-size:12px; margin-bottom:4px;}\n.building .b-status{font-size:11px; padding:3px 8px; border-radius:6px; display:inline-block;}\n.b-status.ok{background:var(--green-dim); color:var(--green);}\n.b-status.down{background:var(--red-dim); color:var(--red-bright);}\n.building.failed{opacity:.4; filter:grayscale(1); transform:translateY(4px);}\n.building.shaking{animation:shake .4s;}\n@keyframes shake{0%,100%{transform:translateX(0);}25%{transform:translateX(-4px);}75%{transform:translateX(4px);}}\n.fd-rack{display:flex; gap:14px; justify-content:center; margin:20px 0; flex-wrap:wrap;}\n.rack{width:150px; border:1px solid var(--border-strong); border-radius:8px; padding:8px; background:var(--panel);}\n.rack .rack-head{font-family:var(--font-mono); font-size:11px; text-align:center; color:var(--text-3); margin-bottom:6px;}\n.rack-slot{height:20px; border-radius:4px; background:var(--panel-2); margin-bottom:4px; font-size:9px; display:flex; align-items:center; justify-content:center; color:var(--text-3); border:1px solid var(--border);}\n.rack-slot.filled{background:var(--blue-dim); color:var(--blue); border-color:rgba(79,140,255,.4); font-weight:700;}\n.rack.dead{opacity:.35;}\n.rack.dead .rack-slot.filled{background:var(--red-dim); color:var(--red-bright);}\n.calc-grid{display:grid; grid-template-columns:1fr 1fr; gap:24px;}\n@media (max-width:800px){.calc-grid{grid-template-columns:1fr;}}\n.calc-row{display:flex; align-items:center; justify-content:space-between; gap:10px; margin-bottom:14px;}\n.calc-row label{font-size:13px; color:var(--text-2);}\n.calc-row output{font-family:var(--font-mono); color:var(--red-bright); font-weight:700; font-size:13px;}\ncanvas#capexChart{width:100%; height:220px;}\n.cost-total{display:flex; justify-content:space-between; padding-top:14px; border-top:1px solid var(--border); margin-top:6px;}\n.cost-total b{font-family:var(--font-display); font-size:20px;}\n.policy-editor{background:#0c0d10; border:1px solid var(--border-strong); border-radius:var(--radius-sm); padding:16px; font-family:var(--font-mono); font-size:13.5px;}\n.policy-editor textarea{width:100%; min-height:80px; background:transparent; border:none; outline:none; color:#e8e8ea; font-family:var(--font-mono); font-size:13.5px; resize:vertical; line-height:1.7;}\n.policy-verdict{margin-top:10px; padding:10px 12px; border-radius:8px; font-size:12.5px; font-family:var(--font-body); display:none;}\n.policy-verdict.ok{display:block; background:var(--green-dim); color:var(--green);}\n.policy-verdict.bad{display:block; background:var(--red-dim); color:var(--red-bright);}\n.console-sim{border:1px solid var(--border-strong); border-radius:var(--radius); overflow:hidden; background:var(--panel);}\n.console-tb{display:flex; align-items:center; gap:10px; background:var(--panel-2); padding:10px 14px; border-bottom:1px solid var(--border);}\n.console-tb .dots span{width:10px; height:10px; border-radius:50%; display:inline-block; margin-right:5px;}\n.console-body{display:flex; min-height:320px;}\n.console-nav{width:170px; border-right:1px solid var(--border); padding:12px 8px; flex-shrink:0;}\n.console-nav div{padding:8px 10px; font-size:12.5px; border-radius:6px; cursor:pointer; color:var(--text-2); margin-bottom:2px;}\n.console-nav div.active{background:var(--red-dim); color:var(--red-bright); font-weight:700;}\n.console-main{flex:1; padding:16px;}\n.console-toolbar{display:flex; gap:8px; margin-bottom:14px;}\n.console-table{width:100%; font-size:12.5px; border-collapse:collapse;}\n.console-table th{text-align:left; font-size:10px; text-transform:uppercase; color:var(--text-3); padding:6px 8px; border-bottom:1px solid var(--border-strong);}\n.console-table td{padding:8px; border-bottom:1px solid var(--border); color:var(--text-2);}\n.console-table tr:hover td{background:var(--panel-2);}\n.status-pill{font-size:10px; padding:2px 8px; border-radius:20px;}\n.status-pill.active{background:var(--green-dim); color:var(--green);}\n.status-pill.deleted{background:var(--red-dim); color:var(--red-bright);}\n.mini-input{background:var(--panel-2); border:1px solid var(--border-strong); color:var(--text-1); border-radius:6px; padding:6px 10px; font-size:12.5px; font-family:var(--font-body);}\n.terminal{background:#0a0b0d; border:1px solid var(--border-strong); border-radius:var(--radius); overflow:hidden;}\n.terminal-tb{background:#16171c; padding:8px 14px; font-size:11px; color:var(--text-3); font-family:var(--font-mono); border-bottom:1px solid var(--border);}\n#term-out{padding:16px; font-family:var(--font-mono); font-size:12.5px; color:#c9f7d8; height:280px; overflow-y:auto; white-space:pre-wrap;}\n#term-out .cmdline{color:#7db2ff;}\n#term-out .cmdline::before{content:\"$ \"; color:var(--red-bright);}\n.term-input-row{display:flex; align-items:center; gap:8px; padding:10px 16px; border-top:1px solid var(--border); font-family:var(--font-mono); font-size:12.5px;}\n.term-input-row span{color:var(--red-bright);}\n#term-input{flex:1; background:transparent; border:none; outline:none; color:#e8e8ea; font-family:var(--font-mono); font-size:12.5px;}\n.tree{font-size:13.5px;}\n.tree ul{list-style:none; margin-left:22px; border-left:1px dashed var(--border-strong); padding-left:18px;}\n.tree li{margin:6px 0; position:relative;}\n.tree .node{display:inline-flex; align-items:center; gap:6px; padding:5px 10px; border-radius:6px; cursor:pointer; transition:.15s;}\n.tree .node:hover{background:var(--panel-2);}\n.tree .node .ic{font-size:13px;}\n.tree .node.root{color:var(--red-bright); font-weight:700;}\n.flash-wrap{display:grid; grid-template-columns:repeat(3,1fr); gap:16px;}\n@media (max-width:800px){.flash-wrap{grid-template-columns:1fr 1fr;}}\n@media (max-width:520px){.flash-wrap{grid-template-columns:1fr;}}\n.flashcard{perspective:1000px; height:130px; cursor:pointer;}\n.flashcard .fc-inner{position:relative; width:100%; height:100%; transition:transform .5s; transform-style:preserve-3d;}\n.flashcard.flipped .fc-inner{transform:rotateY(180deg);}\n.fc-face{position:absolute; inset:0; backface-visibility:hidden; border-radius:var(--radius-sm); border:1px solid var(--border-strong); padding:14px; display:flex; align-items:center; justify-content:center; text-align:center; font-size:13px;}\n.fc-front{background:var(--panel);}\n.fc-back{background:var(--red-dim); color:var(--red-bright); transform:rotateY(180deg); font-weight:600;}\n.quiz-q{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:18px 20px; margin-bottom:14px;}\n.quiz-q .qtext{font-size:14.5px; font-weight:600; margin-bottom:12px;}\n.quiz-opts{display:flex; flex-direction:column; gap:8px;}\n.quiz-opt{display:flex; align-items:center; gap:10px; padding:10px 14px; border-radius:8px; border:1px solid var(--border); cursor:pointer; font-size:13.5px; color:var(--text-2); transition:.15s;}\n.quiz-opt:hover{border-color:var(--border-strong); background:var(--panel-2);}\n.quiz-opt input{accent-color:var(--red);}\n.quiz-opt.correct{border-color:var(--green); background:var(--green-dim); color:var(--green);}\n.quiz-opt.incorrect{border-color:var(--red); background:var(--red-dim); color:var(--red-bright);}\n.quiz-explain{font-size:12.5px; color:var(--text-3); margin-top:10px; display:none; padding-top:10px; border-top:1px dashed var(--border);}\n.quiz-q.answered .quiz-explain{display:block;}\n#badge-wrap{text-align:center; padding:60px 20px;}\n.badge-circle{width:150px; height:150px; border-radius:50%; margin:0 auto 20px; position:relative; background:conic-gradient(var(--red-bright) 0deg, var(--red) var(--pct,0deg), var(--panel-2) var(--pct,0deg)); display:flex; align-items:center; justify-content:center; transition:background 1s ease;}\n.badge-circle::before{content:\"\"; position:absolute; inset:10px; border-radius:50%; background:var(--void);}\n.badge-circle span{position:relative; font-family:var(--font-display); font-size:28px; font-weight:700;}\n.center{text-align:center;}\n.mt-lg{margin-top:36px;}\n.small{font-size:12px; color:var(--text-3);}\nfooter{text-align:center; padding:50px 20px; color:var(--text-3); font-size:12.5px; border-top:1px solid var(--border); margin-top:60px;}\n.toc-jump{display:flex; gap:8px; flex-wrap:wrap; margin-top:18px;}\n\n\n/* ============================================================\n   DAY 11 \u2014 REVISION & CERTIFICATION WIDGET STYLES\n   (day recap cards, knowledge map, skill check engine,\n   architecture discussion, MCQ practice banks, timed mock\n   exam engine, scenario labs, interview prep, doubt search,\n   radar chart, certification dashboard)\n   ============================================================ */\n\n/* --- day recap cards --- */\n.day-recap-grid{display:grid; grid-template-columns:repeat(auto-fill,minmax(220px,1fr)); gap:14px;}\n.day-recap-card{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:16px; cursor:pointer; transition:.2s;}\n.day-recap-card:hover{border-color:var(--red);}\n.day-recap-card .dnum{font-family:var(--font-mono); font-size:11px; color:var(--red-bright); background:var(--red-dim); padding:2px 8px; border-radius:6px; display:inline-block; margin-bottom:8px;}\n.day-recap-detail{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:16px; margin-top:14px; font-size:13.5px; color:var(--text-2); min-height:60px; display:none;}\n.day-recap-detail.show{display:block;}\n\n/* --- knowledge map --- */\n.kmap-svg{width:100%; height:auto;}\n.kmap-node{cursor:pointer;}\n.kmap-node:hover circle, .kmap-node.active circle{filter:brightness(1.4);}\n.kmap-detail{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:16px; margin-top:14px; font-size:13.5px; color:var(--text-2); min-height:70px;}\n\n/* --- skill check engine --- */\n.sc-diff-row{display:flex; gap:8px; margin-bottom:14px;}\n.sc-type-badge{font-size:10px; text-transform:uppercase; letter-spacing:.05em; padding:3px 10px; border-radius:20px; background:var(--blue-dim); color:var(--blue); display:inline-block; margin-bottom:8px;}\n.sc-hint-box{background:var(--amber-dim); border:1px solid rgba(232,163,61,.35); color:var(--amber); border-radius:8px; padding:10px 14px; font-size:12.5px; margin-top:10px; display:none;}\n\n/* --- architecture discussion --- */\n.arch-eval-grid{display:grid; grid-template-columns:repeat(auto-fit,minmax(150px,1fr)); gap:10px; margin-top:14px;}\n.arch-eval-item{background:var(--panel); border:1px solid var(--border); border-radius:8px; padding:10px; text-align:center; font-size:12px;}\n.arch-eval-item select{width:100%; margin-top:6px;}\n\n/* --- practice question bank --- */\n.qbank-controls{display:flex; gap:8px; flex-wrap:wrap; margin-bottom:14px; align-items:center;}\n.qbank-progress{font-size:12.5px; color:var(--text-3);}\n.qbank-card{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:18px; margin-bottom:14px;}\n.qbank-meta{display:flex; gap:8px; flex-wrap:wrap; margin-bottom:10px;}\n.qbank-meta span{font-size:10px; text-transform:uppercase; letter-spacing:.04em; padding:2px 9px; border-radius:20px; background:var(--panel-2); color:var(--text-3);}\n.qbank-meta .diff-easy{color:var(--green);} .qbank-meta .diff-medium{color:var(--amber);} .qbank-meta .diff-hard{color:var(--red-bright);}\n.qbank-bookmark{cursor:pointer; float:right; font-size:16px;}\n.qbank-refnote{font-size:11.5px; color:var(--text-3); margin-top:10px; padding-top:10px; border-top:1px dashed var(--border); display:none;}\n.qbank-refnote.show{display:block;}\n\n/* --- mock exam engine --- */\n.exam-setup-grid{display:grid; grid-template-columns:repeat(auto-fit,minmax(120px,1fr)); gap:10px;}\n.exam-len-card{background:var(--panel); border:1px solid var(--border-strong); border-radius:var(--radius-sm); padding:16px; text-align:center; cursor:pointer; transition:.2s;}\n.exam-len-card:hover, .exam-len-card.selected{border-color:var(--red); background:var(--red-dim);}\n.exam-len-card .n{font-family:var(--font-display); font-size:24px;}\n.exam-toolbar{display:flex; justify-content:space-between; align-items:center; padding:12px 16px; background:var(--panel-2); border-radius:8px; margin-bottom:14px; flex-wrap:wrap; gap:10px;}\n.exam-timer{font-family:var(--font-mono); font-size:18px; color:var(--red-bright);}\n.exam-nav-grid{display:flex; flex-wrap:wrap; gap:6px; margin-bottom:14px;}\n.exam-nav-dot{width:30px; height:30px; border-radius:6px; border:1px solid var(--border-strong); background:var(--panel); font-size:11px; display:flex; align-items:center; justify-content:center; cursor:pointer;}\n.exam-nav-dot.answered{background:var(--blue-dim); border-color:var(--blue); color:var(--blue);}\n.exam-nav-dot.flagged{border-color:var(--amber); box-shadow:0 0 0 2px var(--amber-dim);}\n.exam-nav-dot.current{border-color:var(--red-bright); box-shadow:0 0 0 3px var(--red-dim);}\n.exam-results-grid{display:grid; grid-template-columns:repeat(auto-fit,minmax(140px,1fr)); gap:12px;}\n\n/* --- scenario labs --- */\n.scenario-lab-card{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:14px; cursor:pointer; text-align:center; transition:.2s;}\n.scenario-lab-card:hover{border-color:var(--red);}\n.scenario-score-grid{display:grid; grid-template-columns:repeat(3,1fr); gap:10px; margin-top:14px;}\n\n/* --- interview prep --- */\n.interview-filters{display:flex; gap:6px; flex-wrap:wrap; margin-bottom:14px;}\n.interview-card{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:16px; margin-bottom:10px;}\n.interview-q{font-weight:700; font-size:13.5px; margin-bottom:8px; cursor:pointer;}\n.interview-a{font-size:13px; color:var(--text-2); display:none;}\n.interview-a.show{display:block;}\n.interview-a .ia-label{font-size:10px; text-transform:uppercase; color:var(--red-bright); letter-spacing:.05em; margin:8px 0 3px;}\n\n/* --- doubt clearing search --- */\n.doubt-result-card{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:16px; margin-bottom:10px;}\n\n/* --- radar chart (weak area) --- */\ncanvas#radarChart{width:100%; max-width:420px; display:block; margin:0 auto;}\n\n/* --- certification dashboard --- */\n.certdash-grid{display:grid; grid-template-columns:repeat(auto-fit,minmax(160px,1fr)); gap:14px;}\n.readiness-meter{height:20px; border-radius:12px; background:var(--panel-2); overflow:hidden; margin:10px 0;}\n.readiness-fill{height:100%; background:linear-gradient(90deg,var(--red),var(--amber),var(--green)); transition:width .8s ease;}\n\n", "html": "\nHTMLEOF\nwc -l head.html<canvas id=\"particles\"></canvas>\n<div id=\"progress-bar\"></div>\n<div id=\"topbar\">\n  <button id=\"sidebar-toggle\" title=\"Toggle sidebar\">\u2630</button>\n  <div class=\"brand\"><span class=\"dot\"></span> OCI Complete Revision &amp; Certification Prep \u00b7 Day 11</div>\n  <div id=\"search-wrap\">\n    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"M21 21l-4.3-4.3\"/></svg>\n    <input id=\"search\" type=\"text\" placeholder=\"Search any topic from Day 1-10\u2026\" autocomplete=\"off\">\n    <div id=\"search-results\"></div>\n  </div>\n  <div class=\"topbar-spacer\"></div>\n  <div id=\"score-chip\">Practice score: <b id=\"score-chip-val\">0/0</b></div>\n  <button id=\"theme-toggle\" title=\"Toggle theme\">\ud83c\udf19</button>\n</div>\n<div id=\"shell\">\n  <nav id=\"sidebar\">\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 1-2 \u00b7 Revision &amp; Map</div>\n      <a class=\"nav-link\" href=\"#sec-courserevision\"><span class=\"num\">01</span>Complete Course Revision</a>\n      <a class=\"nav-link\" href=\"#sec-knowledgemap\"><span class=\"num\">02</span>Cross-Domain Knowledge Map</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 3-5 \u00b7 Skill Building</div>\n      <a class=\"nav-link\" href=\"#sec-skillcheck\"><span class=\"num\">03</span>Oracle Skill Check</a>\n      <a class=\"nav-link\" href=\"#sec-archdiscussion\"><span class=\"num\">04</span>Architecture Discussion Center</a>\n      <a class=\"nav-link\" href=\"#sec-patternexplorer\"><span class=\"num\">05</span>Exam Question Pattern Explorer</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 6 \u00b7 MCQ Practice Bank</div>\n      <a class=\"nav-link\" href=\"#sec-practiceset1\"><span class=\"num\">06</span>Set 1: Foundations, IAM, Security</a>\n      <a class=\"nav-link\" href=\"#sec-practiceset2\"><span class=\"num\">07</span>Set 2: Terraform, Networking, Compute</a>\n      <a class=\"nav-link\" href=\"#sec-practiceset3\"><span class=\"num\">08</span>Set 3: Vault, Encryption, HA/DR</a>\n      <a class=\"nav-link\" href=\"#sec-practiceset4\"><span class=\"num\">09</span>Set 4: Troubleshooting, Monitoring, Audit</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 7-8 \u00b7 Exams &amp; Scenarios</div>\n      <a class=\"nav-link\" href=\"#sec-mockexams\"><span class=\"num\">10</span>Timed Mock Exams</a>\n      <a class=\"nav-link\" href=\"#sec-scenariolabs\"><span class=\"num\">11</span>Scenario Labs</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 9-10 \u00b7 Prep &amp; Doubts</div>\n      <a class=\"nav-link\" href=\"#sec-interviewprep\"><span class=\"num\">12</span>Interview Preparation Center</a>\n      <a class=\"nav-link\" href=\"#sec-doubtclearing\"><span class=\"num\">13</span>Doubt Clearing Center</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 11-12 \u00b7 Analytics</div>\n      <a class=\"nav-link\" href=\"#sec-weakarea\"><span class=\"num\">14</span>Weak Area Analysis</a>\n      <a class=\"nav-link\" href=\"#sec-certdashboard\"><span class=\"num\">15</span>Certification Dashboard</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 13-14 \u00b7 Final Prep</div>\n      <a class=\"nav-link\" href=\"#sec-finalrevision\"><span class=\"num\">16</span>Final Revision Center</a>\n      <a class=\"nav-link\" href=\"#sec-flashcards11\"><span class=\"num\">17</span>Flash Cards</a>\n      <a class=\"nav-link\" href=\"#sec-finalchallenge\"><span class=\"num\">18</span>Final Certification Challenge</a>\n      <a class=\"nav-link\" href=\"#sec-cert11\"><span class=\"num\">19</span>Certificate Preview</a>\n    </div>\n  </nav>\n  <main>\n    <section id=\"hero\">\n      <span class=\"eyebrow\">\u25cf Oracle Cloud Infrastructure \u2014 Complete Revision &amp; Certification Prep</span>\n      <h1>Day 11: Everything you learned.<br><span class=\"accent\">One final pass.</span></h1>\n      <p class=\"lede\">A full recap of Days 1-10, a cross-domain knowledge map, Oracle-style skill checks, a real MCQ practice bank, timed mock exams, scenario labs, interview prep, and a personalized readiness meter.</p>\n      <div class=\"hero-stats\">\n        <div class=\"hstat\"><b>19</b><span>Interactive sections</span></div>\n        <div class=\"hstat\"><b id=\"hero-quiz-count\">48+</b><span>Practice questions</span></div>\n        <div class=\"hstat\"><b>10</b><span>Days recapped</span></div>\n        <div class=\"hstat\"><b id=\"hero-progress\">0%</b><span>Your progress</span></div>\n      </div>\n      <div class=\"cta-row\">\n        <a href=\"#sec-courserevision\" class=\"btn btn-primary\">Start the final revision \u2192</a>\n        <a href=\"#sec-mockexams\" class=\"btn btn-ghost\">Jump to mock exam</a>\n      </div>\n    </section>\n    <div class=\"container\">\n<!-- 01 COMPLETE COURSE REVISION -->\n<section class=\"chapter reveal\" id=\"sec-courserevision\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">01</span><span class=\"track\">Revision &amp; Map</span></div>\n  <h2>Complete Course Revision</h2>\n  <p class=\"dek\">Click any day to recap its core concepts in one paragraph.</p>\n  <div class=\"day-recap-grid\" id=\"day-recap-grid\"></div>\n  <div class=\"day-recap-detail\" id=\"day-recap-detail\"></div>\n</section>\n\n<!-- 02 CROSS-DOMAIN KNOWLEDGE MAP -->\n<section class=\"chapter reveal\" id=\"sec-knowledgemap\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">02</span><span class=\"track\">Revision &amp; Map</span></div>\n  <h2>Cross-Domain Knowledge Map</h2>\n  <p class=\"dek\">Click any service to see its dependencies, related services, and common mistakes.</p>\n  <div class=\"panel\">\n    <svg viewBox=\"0 0 700 420\" class=\"kmap-svg\" id=\"kmap-svg\"></svg>\n    <div class=\"kmap-detail\" id=\"kmap-detail\">Click a node above, starting with IAM at the center.</div>\n  </div>\n</section>\n<!-- 03 ORACLE SKILL CHECK -->\n<section class=\"chapter reveal\" id=\"sec-skillcheck\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">03</span><span class=\"track\">Skill Building</span></div>\n  <h2>Oracle Skill Check</h2>\n  <p class=\"dek\">Oracle University-style checks \u2014 conceptual, applied, architecture, and troubleshooting questions, with hints available.</p>\n  <div class=\"panel\">\n    <div class=\"sc-diff-row\" id=\"sc-type-btns\">\n      <button class=\"chip-btn active\" data-sctype=\"conceptual\">Conceptual</button>\n      <button class=\"chip-btn\" data-sctype=\"applied\">Applied</button>\n      <button class=\"chip-btn\" data-sctype=\"architecture\">Architecture</button>\n      <button class=\"chip-btn\" data-sctype=\"troubleshooting\">Troubleshooting</button>\n    </div>\n    <div id=\"sc-question-area\"></div>\n    <div style=\"display:flex; gap:8px; margin-top:14px;\">\n      <button class=\"chip-btn\" id=\"sc-hint-btn\">\ud83d\udca1 Show hint</button>\n      <button class=\"chip-btn active\" id=\"sc-next-btn\">Next question \u2192</button>\n    </div>\n    <div class=\"sc-hint-box\" id=\"sc-hint-box\"></div>\n  </div>\n</section>\n\n<!-- 04 ARCHITECTURE DISCUSSION CENTER -->\n<section class=\"chapter reveal\" id=\"sec-archdiscussion\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">04</span><span class=\"track\">Skill Building</span></div>\n  <h2>Architecture Discussion Center</h2>\n  <p class=\"dek\">Pick an industry, rate the proposed architecture across 6 dimensions, then compare against expert review.</p>\n  <div class=\"cost-filters\" id=\"archdisc-industry-btns\">\n    <button class=\"chip-btn active\" data-adind=\"banking\">\ud83c\udfe6 Banking</button>\n    <button class=\"chip-btn\" data-adind=\"healthcare\">\ud83c\udfe5 Healthcare</button>\n    <button class=\"chip-btn\" data-adind=\"retail\">\ud83d\uded2 Retail</button>\n    <button class=\"chip-btn\" data-adind=\"manufacturing\">\ud83c\udfed Manufacturing</button>\n    <button class=\"chip-btn\" data-adind=\"government\">\ud83c\udfdb Government</button>\n    <button class=\"chip-btn\" data-adind=\"saas\">\u2601\ufe0f SaaS</button>\n  </div>\n  <div class=\"panel mt-lg\">\n    <p class=\"mono\" id=\"archdisc-scenario\" style=\"color:var(--blue);\"></p>\n    <div class=\"arch-eval-grid\" id=\"archdisc-eval-grid\"></div>\n    <button class=\"chip-btn active mt-lg\" id=\"archdisc-review\">Get expert review</button>\n    <div class=\"lw-boot-log\" id=\"archdisc-expert\" style=\"display:none;\"></div>\n  </div>\n</section>\n\n<!-- 05 EXAM QUESTION PATTERN EXPLORER -->\n<section class=\"chapter reveal\" id=\"sec-patternexplorer\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">05</span><span class=\"track\">Skill Building</span></div>\n  <h2>Exam Question Pattern Explorer</h2>\n  <p class=\"dek\">Oracle exam questions follow recognizable patterns. Learning to spot them saves real time.</p>\n  <div class=\"grid grid-2\">\n    <div class=\"card\"><h4>\ud83d\udd11 Keyword Recognition</h4><p>Words like \"MUST\", \"ALWAYS\", \"MINIMUM cost\", or \"MOST secure\" signal exactly which dimension the question is testing \u2014 read them twice.</p></div>\n    <div class=\"card\"><h4>\u2702\ufe0f Elimination Technique</h4><p>Eliminate options that are factually wrong first, then choose between the remaining two based on the specific constraint given.</p></div>\n    <div class=\"card\"><h4>\ud83d\udcd6 Scenario Analysis</h4><p>Underline the actual constraint (compliance, cost, latency) \u2014 many wrong answers are technically valid but don't fit the stated constraint.</p></div>\n    <div class=\"card\"><h4>\u23f1 Time Management</h4><p>Budget roughly 90 seconds/question; flag and move on if stuck past that \u2014 don't let one question consume your buffer.</p></div>\n  </div>\n  <div class=\"panel mt-lg\">\n    <p><strong>Try it:</strong> \"A company needs the <u>MOST cost-effective</u> way to retain compliance logs for 7 years, rarely accessed.\"</p>\n    <div class=\"quiz-opts mt-lg\" id=\"pattern-demo-opts\">\n      <label class=\"quiz-opt\"><input type=\"radio\" name=\"patterndemo\" value=\"wrong1\">Standard Object Storage tier</label>\n      <label class=\"quiz-opt\"><input type=\"radio\" name=\"patterndemo\" value=\"right\">Archive Storage tier</label>\n      <label class=\"quiz-opt\"><input type=\"radio\" name=\"patterndemo\" value=\"wrong2\">Block Volume with backups</label>\n    </div>\n    <button class=\"chip-btn active mt-lg\" id=\"pattern-demo-check\">Check</button>\n    <p class=\"small mt-lg\" id=\"pattern-demo-result\"></p>\n  </div>\n</section>\n<!-- 06 PRACTICE SET 1 -->\n<section class=\"chapter reveal\" id=\"sec-practiceset1\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">06</span><span class=\"track\">MCQ Practice Bank</span></div>\n  <h2>Practice Set 1: Cloud Foundations, IAM, Security, Governance, Cost</h2>\n  <p class=\"dek\">A curated set from this domain \u2014 each with a scenario, explanation, Oracle doc reference, and bookmark option.</p>\n  <div class=\"qbank-controls\"><span class=\"qbank-progress\" id=\"qb1-progress\">0/12 answered</span></div>\n  <div id=\"qbank-set-1\"></div>\n</section>\n\n<!-- 07 PRACTICE SET 2 -->\n<section class=\"chapter reveal\" id=\"sec-practiceset2\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">07</span><span class=\"track\">MCQ Practice Bank</span></div>\n  <h2>Practice Set 2: Terraform, Networking, VCN, Compute, Storage</h2>\n  <div class=\"qbank-controls\"><span class=\"qbank-progress\" id=\"qb2-progress\">0/12 answered</span></div>\n  <div id=\"qbank-set-2\"></div>\n</section>\n\n<!-- 08 PRACTICE SET 3 -->\n<section class=\"chapter reveal\" id=\"sec-practiceset3\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">08</span><span class=\"track\">MCQ Practice Bank</span></div>\n  <h2>Practice Set 3: Vault, Encryption, KMS, HA, DR</h2>\n  <div class=\"qbank-controls\"><span class=\"qbank-progress\" id=\"qb3-progress\">0/12 answered</span></div>\n  <div id=\"qbank-set-3\"></div>\n</section>\n\n<!-- 09 PRACTICE SET 4 -->\n<section class=\"chapter reveal\" id=\"sec-practiceset4\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">09</span><span class=\"track\">MCQ Practice Bank</span></div>\n  <h2>Practice Set 4: Troubleshooting, Monitoring, Logging, Audit, Governance</h2>\n  <div class=\"qbank-controls\"><span class=\"qbank-progress\" id=\"qb4-progress\">0/12 answered</span></div>\n  <div id=\"qbank-set-4\"></div>\n</section>\n<!-- 10 TIMED MOCK EXAMS -->\n<section class=\"chapter reveal\" id=\"sec-mockexams\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">10</span><span class=\"track\">Exams &amp; Scenarios</span></div>\n  <h2>Timed Mock Exams</h2>\n  <p class=\"dek\">Choose a length \u2014 questions are drawn from the full practice bank (repeating with reshuffles for longer exams). Includes countdown, pause/resume, review flags, and an optional negative-marking mode.</p>\n  <div class=\"panel\" id=\"exam-setup-panel\">\n    <div class=\"exam-setup-grid\" id=\"exam-len-grid\">\n      <div class=\"exam-len-card\" data-len=\"30\"><div class=\"n\">30</div><span class=\"small\">~25 min</span></div>\n      <div class=\"exam-len-card\" data-len=\"60\"><div class=\"n\">60</div><span class=\"small\">~50 min</span></div>\n      <div class=\"exam-len-card\" data-len=\"90\"><div class=\"n\">90</div><span class=\"small\">~75 min</span></div>\n      <div class=\"exam-len-card\" data-len=\"120\"><div class=\"n\">120</div><span class=\"small\">~100 min</span></div>\n    </div>\n    <div class=\"field-row mt-lg\"><label><input type=\"checkbox\" id=\"exam-negative-toggle\"> Enable negative marking (-0.25 per wrong answer)</label></div>\n    <button class=\"chip-btn active mt-lg\" id=\"exam-start-btn\">\u25b6 Start Mock Exam</button>\n  </div>\n  <div class=\"panel\" id=\"exam-run-panel\" style=\"display:none;\">\n    <div class=\"exam-toolbar\">\n      <span class=\"exam-timer\" id=\"exam-timer\">00:00</span>\n      <span><button class=\"chip-btn\" id=\"exam-pause-btn\">\u23f8 Pause</button> <button class=\"chip-btn\" id=\"exam-flag-btn\">\ud83d\udea9 Flag for review</button> <button class=\"chip-btn active\" id=\"exam-submit-btn\">Submit Exam</button></span>\n    </div>\n    <div class=\"exam-nav-grid\" id=\"exam-nav-grid\"></div>\n    <div id=\"exam-question-area\"></div>\n    <div style=\"display:flex; justify-content:space-between; margin-top:14px;\">\n      <button class=\"chip-btn\" id=\"exam-prev-btn\">\u2190 Previous</button>\n      <button class=\"chip-btn active\" id=\"exam-next-btn\">Next \u2192</button>\n    </div>\n  </div>\n  <div class=\"panel\" id=\"exam-results-panel\" style=\"display:none;\">\n    <h3>Results</h3>\n    <div class=\"exam-results-grid\" id=\"exam-results-grid\"></div>\n    <canvas id=\"examPerfChart\" width=\"500\" height=\"180\" class=\"mt-lg\"></canvas>\n  </div>\n</section>\n\n<!-- 11 SCENARIO LABS -->\n<section class=\"chapter reveal\" id=\"sec-scenariolabs\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">11</span><span class=\"track\">Exams &amp; Scenarios</span></div>\n  <h2>Scenario Labs</h2>\n  <p class=\"dek\">Real operational scenarios pulling on everything from the course. Scored on accuracy, speed, and decision quality.</p>\n  <div class=\"grid grid-3\" id=\"scenario-lab-grid\"></div>\n  <div class=\"panel mt-lg\" id=\"scenario-lab-detail\" style=\"display:none;\"></div>\n</section>\n<!-- 12 INTERVIEW PREPARATION CENTER -->\n<section class=\"chapter reveal\" id=\"sec-interviewprep\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">12</span><span class=\"track\">Prep &amp; Doubts</span></div>\n  <h2>Interview Preparation Center</h2>\n  <p class=\"dek\">Click a question to reveal the ideal answer, alternative framing, common mistakes, and likely follow-ups.</p>\n  <div class=\"interview-filters\" id=\"interview-cat-btns\">\n    <button class=\"chip-btn active\" data-icat=\"all\">All</button>\n    <button class=\"chip-btn\" data-icat=\"fundamentals\">Cloud Fundamentals</button>\n    <button class=\"chip-btn\" data-icat=\"networking\">Networking</button>\n    <button class=\"chip-btn\" data-icat=\"security\">Security</button>\n    <button class=\"chip-btn\" data-icat=\"terraform\">Terraform</button>\n    <button class=\"chip-btn\" data-icat=\"troubleshooting\">Troubleshooting</button>\n    <button class=\"chip-btn\" data-icat=\"behavioral\">Behavioral</button>\n  </div>\n  <div id=\"interview-list\"></div>\n</section>\n\n<!-- 13 DOUBT CLEARING CENTER -->\n<section class=\"chapter reveal\" id=\"sec-doubtclearing\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">13</span><span class=\"track\">Prep &amp; Doubts</span></div>\n  <h2>Doubt Clearing Center</h2>\n  <p class=\"dek\">Type a topic, keyword, CLI command, or error message from anywhere in the course.</p>\n  <div class=\"panel\">\n    <input class=\"mini-input\" id=\"doubt-search\" placeholder=\"e.g. 'NSG', 'terraform state', 'NotAuthorizedOrNotFound', 'RPO'\" style=\"width:100%;\">\n    <div id=\"doubt-results\" class=\"mt-lg\"></div>\n  </div>\n</section>\n<!-- 14 WEAK AREA ANALYSIS -->\n<section class=\"chapter reveal\" id=\"sec-weakarea\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">14</span><span class=\"track\">Analytics</span></div>\n  <h2>Personalized Weak Area Analysis</h2>\n  <p class=\"dek\">This radar chart updates live as you answer questions anywhere on this page \u2014 practice sets, skill checks, mock exams, and scenario labs all feed into it.</p>\n  <div class=\"panel center\">\n    <canvas id=\"radarChart\" width=\"420\" height=\"360\"></canvas>\n  </div>\n  <div class=\"grid grid-2 mt-lg\">\n    <div class=\"card\"><h4>Strongest domain</h4><p id=\"weakarea-strong\">Answer a few questions to see this update.</p></div>\n    <div class=\"card\"><h4>Weakest domain</h4><p id=\"weakarea-weak\">Answer a few questions to see this update.</p></div>\n  </div>\n</section>\n\n<!-- 15 CERTIFICATION DASHBOARD -->\n<section class=\"chapter reveal\" id=\"sec-certdashboard\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">15</span><span class=\"track\">Analytics</span></div>\n  <h2>Certification Dashboard</h2>\n  <div class=\"certdash-grid\">\n    <div class=\"score-kpi\"><div class=\"score-ring-sm\" id=\"cd-accuracy-ring\" style=\"--s:0;\"><span id=\"cd-accuracy-val\">0%</span></div><div class=\"k-label\">Average Accuracy</div></div>\n    <div class=\"score-kpi\"><div class=\"score-ring-sm\" id=\"cd-progress-ring\" style=\"--s:0; --ring-color:var(--blue);\"><span id=\"cd-progress-val\">0%</span></div><div class=\"k-label\">Course Progress</div></div>\n    <div class=\"score-kpi\"><div class=\"score-ring-sm\" id=\"cd-questions-ring\" style=\"--s:0; --ring-color:var(--amber);\"><span id=\"cd-questions-val\">0</span></div><div class=\"k-label\">Questions Attempted</div></div>\n  </div>\n  <div class=\"panel mt-lg\">\n    <p><strong>Exam Readiness</strong></p>\n    <div class=\"readiness-meter\"><div class=\"readiness-fill\" id=\"readiness-fill\" style=\"width:0%;\"></div></div>\n    <p class=\"small\" id=\"readiness-text\">Answer more questions across the practice sets to build your readiness estimate.</p>\n  </div>\n</section>\n<!-- 16 FINAL REVISION CENTER -->\n<section class=\"chapter reveal\" id=\"sec-finalrevision\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">16</span><span class=\"track\">Final Prep</span></div>\n  <h2>Final Revision Center</h2>\n  <p class=\"dek\">The master cheat sheet \u2014 every domain, one screen each.</p>\n  <div class=\"cost-filters\" id=\"finalrev-tabs\">\n    <button class=\"chip-btn active\" data-frtab=\"iam\">IAM &amp; Governance</button>\n    <button class=\"chip-btn\" data-frtab=\"networking\">Networking</button>\n    <button class=\"chip-btn\" data-frtab=\"compute\">Compute &amp; Storage</button>\n    <button class=\"chip-btn\" data-frtab=\"terraform\">Terraform</button>\n    <button class=\"chip-btn\" data-frtab=\"security\">Security &amp; Vault</button>\n    <button class=\"chip-btn\" data-frtab=\"hadr\">HA/DR</button>\n    <button class=\"chip-btn\" data-frtab=\"monitoring\">Monitoring &amp; Logging</button>\n    <button class=\"chip-btn\" data-frtab=\"cli\">CLI Reference</button>\n  </div>\n  <div class=\"panel mt-lg\" id=\"finalrev-content\"></div>\n</section>\n\n<!-- 17 FLASHCARDS -->\n<section class=\"chapter reveal\" id=\"sec-flashcards11\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">17</span><span class=\"track\">Final Prep</span></div>\n  <h2>Flash Cards</h2>\n  <p class=\"dek\">One last pass across every domain.</p>\n  <div class=\"flash-wrap\" id=\"flash-wrap11\"></div>\n</section>\n\n<!-- 18 FINAL CERTIFICATION CHALLENGE -->\n<section class=\"chapter reveal\" id=\"sec-finalchallenge\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">18</span><span class=\"track\">Final Prep</span></div>\n  <h2>Final Certification Challenge</h2>\n  <p class=\"dek\">A scored, mixed-domain challenge covering the whole course \u2014 treat this as your dress rehearsal.</p>\n  <div id=\"quiz-wrap11\"></div>\n  <div class=\"panel center mt-lg\"><p>Your score: <b id=\"quiz-final-score11\" style=\"color:var(--red-bright); font-family:var(--font-display); font-size:20px;\">0 / 20</b></p></div>\n</section>\n\n<!-- 19 CERTIFICATE PREVIEW -->\n<section class=\"chapter reveal\" id=\"sec-cert11\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">19</span><span class=\"track\">Final Prep</span></div>\n  <h2>Completion &amp; Certificate Preview</h2>\n  <div class=\"center\" style=\"padding:20px 0 40px;\">\n    <div class=\"badge-circle\" id=\"badge-circle11\"><span id=\"badge-pct11\">0%</span></div>\n    <h3 id=\"badge-title11\">Keep going</h3>\n    <p class=\"small\" id=\"badge-sub11\">Complete every section and the Final Certification Challenge to preview your certificate.</p>\n  </div>\n  <div class=\"cert-frame\">\n    <p class=\"small\">ORACLE CLOUD INFRASTRUCTURE</p>\n    <h3>Certificate of Completion</h3>\n    <p class=\"small\">This certifies that</p>\n    <div class=\"cert-name\">Your Name</div>\n    <p class=\"small\">has completed <strong>Day 11: Complete Revision &amp; Certification Preparation</strong></p>\n    <p class=\"small mt-lg\">Score: <span id=\"cert-score-display11\">0/20</span> \u00b7 Date: <span id=\"cert-date-display11\"></span></p>\n  </div>\n</section>\n\n</div>\n</main>\n</div>\n<footer>OCI Complete Revision, Skill Check &amp; Certification Prep \u2014 Day 11 \u00b7 Interactive Learning Platform \u00b7 Single self-contained HTML file \u00b7 No external dependencies</footer>\n\n\n\n\n\n\n\n\n", "js": "\nconst DOMAINS = ['IAM & Governance','Networking','Compute & Storage','Terraform','Security & Vault','HA/DR','Monitoring & Troubleshooting','Cost'];\nconst state = { quizScore:0, quizAnswered:0, quizTotal:0, labsDone:new Set() };\nconst domainStats = {}; DOMAINS.forEach(d=> domainStats[d] = {correct:0, total:0});\nlet totalQuestionsAttempted = 0;\n\nfunction recordAnswer(domain, correct){\n  if(!domainStats[domain]) domainStats[domain] = {correct:0, total:0};\n  domainStats[domain].total++;\n  if(correct) domainStats[domain].correct++;\n  totalQuestionsAttempted++;\n  drawRadar();\n  updateCertDashboard();\n}\n\ndocument.addEventListener('DOMContentLoaded', () => {\n  initParticles(); initProgressBar(); initSidebar(); initSearch(); initTheme(); initReveal();\n  initDayRecap(); initKnowledgeMap();\n  initSkillCheck(); initArchDiscussion(); initPatternExplorer();\n  initQBank();\n  initMockExam(); initScenarioLabs();\n  initInterviewPrep(); initDoubtClearing();\n  drawRadar(); updateCertDashboard();\n  initFinalRevision(); initFlashcards11(); initQuiz11(); updateBadge11();\n});\nfunction initParticles(){\n  const c=document.getElementById('particles'); const ctx=c.getContext('2d'); let w,h,particles=[];\n  function resize(){ w=c.width=window.innerWidth; h=c.height=window.innerHeight; }\n  resize(); window.addEventListener('resize', resize);\n  const N=Math.min(60, Math.floor(window.innerWidth/24));\n  for(let i=0;i<N;i++) particles.push({x:Math.random()*w,y:Math.random()*h,r:Math.random()*1.6+0.4,vx:(Math.random()-0.5)*0.15,vy:(Math.random()-0.5)*0.15});\n  function tick(){ ctx.clearRect(0,0,w,h); ctx.fillStyle='rgba(199,70,52,0.5)';\n    particles.forEach(p=>{ p.x+=p.vx; p.y+=p.vy; if(p.x<0)p.x=w; if(p.x>w)p.x=0; if(p.y<0)p.y=h; if(p.y>h)p.y=0; ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,Math.PI*2); ctx.fill(); });\n    requestAnimationFrame(tick);\n  }\n  tick();\n}\nfunction initProgressBar(){\n  const bar=document.getElementById('progress-bar'); const heroProgress=document.getElementById('hero-progress');\n  window.addEventListener('scroll', ()=>{\n    const scrollTop=window.scrollY; const docH=document.documentElement.scrollHeight-window.innerHeight;\n    const pct=docH>0?(scrollTop/docH)*100:0;\n    bar.style.width=pct+'%'; if(heroProgress) heroProgress.textContent=Math.round(pct)+'%';\n    window.__lastScrollPct11=pct; updateBadge11(); updateCertDashboard(); highlightActiveNav();\n  }, {passive:true});\n}\nfunction highlightActiveNav(){\n  const sections=document.querySelectorAll('section.chapter'); let current=null;\n  sections.forEach(sec=>{ const rect=sec.getBoundingClientRect(); if(rect.top<160) current=sec.id; });\n  document.querySelectorAll('#sidebar a.nav-link').forEach(a=>a.classList.toggle('active', a.getAttribute('href')==='#'+current));\n}\nfunction initSidebar(){ const sb=document.getElementById('sidebar'); document.getElementById('sidebar-toggle').addEventListener('click', ()=>sb.classList.toggle('collapsed')); }\nfunction initSearch(){\n  const input=document.getElementById('search'); const results=document.getElementById('search-results'); const index=[];\n  document.querySelectorAll('section.chapter').forEach(sec=>{\n    const title=sec.querySelector('h2')?.textContent || sec.id;\n    sec.querySelectorAll('h3').forEach(h3=>index.push({label:h3.textContent, cat:title, href:'#'+sec.id}));\n    index.push({label:title, cat:'Section', href:'#'+sec.id});\n  });\n  input.addEventListener('input', ()=>{\n    const q=input.value.trim().toLowerCase(); if(!q){results.style.display='none'; return;}\n    const matches=index.filter(i=>i.label.toLowerCase().includes(q)).slice(0,8);\n    results.innerHTML=matches.map(m=>`<a href=\"${m.href}\"><span class=\"sr-cat\">${m.cat}</span>${m.label}</a>`).join('') || '<a style=\"cursor:default;\">No results</a>';\n    results.style.display='block';\n  });\n  document.addEventListener('click', e=>{ if(!document.getElementById('search-wrap').contains(e.target)) results.style.display='none'; });\n  results.addEventListener('click', ()=>setTimeout(()=>{results.style.display='none'; input.value='';},10));\n}\nfunction initTheme(){\n  const btn=document.getElementById('theme-toggle');\n  btn.addEventListener('click', ()=>{ const html=document.documentElement; const isDark=html.getAttribute('data-theme')!=='light'; html.setAttribute('data-theme', isDark?'light':'dark'); btn.textContent=isDark?'\u2600\ufe0f':'\ud83c\udf19'; });\n}\nfunction initReveal(){\n  const els=document.querySelectorAll('.reveal');\n  const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('in');}), {threshold:0.08});\n  els.forEach(el=>io.observe(el));\n}\n\n/* ---------- radar chart (weak area analysis) ---------- */\nfunction drawRadar(){\n  const canvas = document.getElementById('radarChart'); if(!canvas) return;\n  const ctx = canvas.getContext('2d');\n  const w = canvas.width = 420, h = canvas.height = 360;\n  ctx.clearRect(0,0,w,h);\n  const cx = w/2, cy = h/2-10, radius = 130;\n  const n = DOMAINS.length;\n  const pcts = DOMAINS.map(d=> domainStats[d].total ? (domainStats[d].correct/domainStats[d].total) : 0.05);\n  // grid rings\n  ctx.strokeStyle = 'rgba(255,255,255,0.08)';\n  for(let ring=1; ring<=4; ring++){\n    ctx.beginPath();\n    for(let i=0;i<=n;i++){\n      const ang = (Math.PI*2*i/n) - Math.PI/2;\n      const r = radius*(ring/4);\n      const x = cx+Math.cos(ang)*r, y = cy+Math.sin(ang)*r;\n      if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);\n    }\n    ctx.stroke();\n  }\n  // axis labels\n  ctx.font = '10px sans-serif'; ctx.fillStyle = '#a7acb8'; ctx.textAlign='center';\n  DOMAINS.forEach((d,i)=>{\n    const ang = (Math.PI*2*i/n) - Math.PI/2;\n    const x = cx+Math.cos(ang)*(radius+34), y = cy+Math.sin(ang)*(radius+34);\n    d.split(' & ').forEach((line,li)=> ctx.fillText(line, x, y+li*11));\n  });\n  // data polygon\n  ctx.beginPath();\n  pcts.forEach((p,i)=>{\n    const ang = (Math.PI*2*i/n) - Math.PI/2;\n    const r = radius*p;\n    const x = cx+Math.cos(ang)*r, y = cy+Math.sin(ang)*r;\n    if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);\n  });\n  ctx.closePath();\n  ctx.fillStyle = 'rgba(199,70,52,0.28)'; ctx.fill();\n  ctx.strokeStyle = '#ff5a3c'; ctx.lineWidth=2; ctx.stroke();\n\n  const withData = DOMAINS.filter(d=> domainStats[d].total>0);\n  const strongEl = document.getElementById('weakarea-strong'); const weakEl = document.getElementById('weakarea-weak');\n  if(strongEl && withData.length){\n    const sorted = [...withData].sort((a,b)=> (domainStats[b].correct/domainStats[b].total) - (domainStats[a].correct/domainStats[a].total));\n    strongEl.textContent = `${sorted[0]} \u2014 ${Math.round((domainStats[sorted[0]].correct/domainStats[sorted[0]].total)*100)}% accuracy`;\n    weakEl.textContent = `${sorted[sorted.length-1]} \u2014 ${Math.round((domainStats[sorted[sorted.length-1]].correct/domainStats[sorted[sorted.length-1]].total)*100)}% accuracy`;\n  }\n}\n\n/* ---------- certification dashboard ---------- */\nfunction updateCertDashboard(){\n  const accRing = document.getElementById('cd-accuracy-ring'); if(!accRing) return;\n  const totalCorrect = Object.values(domainStats).reduce((a,d)=>a+d.correct,0);\n  const totalAnswered = Object.values(domainStats).reduce((a,d)=>a+d.total,0);\n  const accuracy = totalAnswered ? Math.round((totalCorrect/totalAnswered)*100) : 0;\n  accRing.style.setProperty('--s', accuracy); document.getElementById('cd-accuracy-val').textContent = accuracy+'%';\n  const scrollPct = Math.round(window.__lastScrollPct11 || 0);\n  document.getElementById('cd-progress-ring').style.setProperty('--s', scrollPct); document.getElementById('cd-progress-val').textContent = scrollPct+'%';\n  document.getElementById('cd-questions-ring').style.setProperty('--s', Math.min(100, totalAnswered*2)); document.getElementById('cd-questions-val').textContent = totalAnswered;\n  const readiness = Math.round(accuracy*0.6 + scrollPct*0.4);\n  const fill = document.getElementById('readiness-fill');\n  if(fill){ fill.style.width = readiness+'%';\n    const txt = document.getElementById('readiness-text');\n    if(readiness>=80) txt.textContent = `${readiness}% ready \u2014 strong performance across domains. You're in good shape for the real exam.`;\n    else if(readiness>=50) txt.textContent = `${readiness}% ready \u2014 solid progress, but review your weakest domain above before the real exam.`;\n    else txt.textContent = `${readiness}% ready \u2014 keep working through the practice sets and mock exams to build confidence.`;\n  }\n}\n\n;\n\n/* ---------- day recap ---------- */\nfunction initDayRecap(){\n  const wrap = document.getElementById('day-recap-grid'); if(!wrap) return;\n  const days = [\n    ['Day 1: Cloud Foundations', 'Cloud computing fundamentals, virtualization, service/deployment models, OCI global infrastructure (regions/realms/ADs/FDs), tenancy, compartments, IAM basics, and policy syntax.'],\n    ['Day 2: Security &amp; Governance', 'CIA triad, defense in depth, Zero Trust, Cloud Guard, Security Zones, cost management, budgets, and governance fundamentals.'],\n    ['Day 3: Linux, Networking &amp; CLI', 'Linux architecture, filesystem, permissions, processes; full networking stack (OSI, IPv4/CIDR, DNS, TLS); OCI Cloud Shell, CLI, REST API, and SDKs.'],\n    ['Day 4: Terraform &amp; IaC', 'Infrastructure as Code principles, Terraform state management, OCI Resource Manager, and drift detection.'],\n    ['Day 5: VCN &amp; Infrastructure', 'VCN architecture, subnets, gateways (IGW/NAT/SGW/DRG/LPG), Security Lists/NSGs, compute launch, cloud-init, and storage.'],\n    ['Day 6: Encryption, PKI &amp; Vault', 'Symmetric/asymmetric encryption, PKI chain of trust, OCI Vault, KMS, HSM, secrets management, and key rotation.'],\n    ['Day 7: Database &amp; DR', 'Database fundamentals, high availability patterns, disaster recovery strategy, backup, and full-stack DR design.'],\n    ['Day 8: Troubleshooting', 'Structured troubleshooting methodology, compute/SSH issues, VPN/FastConnect, load balancer diagnostics, storage issues, and root cause analysis.'],\n    ['Day 9: Monitoring &amp; Observability', 'Monitoring, Metric Query Language, Logging, Audit, Service Connector Hub, Notifications, Alarms, and capacity planning.'],\n    ['Day 10: Enterprise Operations', 'Enterprise governance, Organization Management, cost optimization, security posture review, compliance readiness, and the capstone case study.'],\n  ];\n  wrap.innerHTML = days.map(([t],i)=>`<div class=\"day-recap-card\" data-i=\"${i}\"><span class=\"dnum\">DAY ${i+1}</span><div>${t.replace(/^Day \\d+: /,'')}</div></div>`).join('');\n  const detail = document.getElementById('day-recap-detail');\n  wrap.querySelectorAll('.day-recap-card').forEach((card,i)=>{\n    card.addEventListener('click', ()=>{\n      detail.classList.add('show');\n      detail.innerHTML = `<strong>${days[i][0]}</strong><p style=\"margin-top:8px;\">${days[i][1]}</p>`;\n    });\n  });\n}\n\n/* ---------- cross-domain knowledge map ---------- */\nfunction initKnowledgeMap(){\n  const svg = document.getElementById('kmap-svg'); if(!svg) return;\n  const nodes = [\n    {id:'iam', label:'IAM', x:350, y:210, r:34, color:'#c74634'},\n    {id:'networking', label:'Networking', x:150, y:120, r:26, color:'#4f8cff'},\n    {id:'compute', label:'Compute', x:350, y:60, r:26, color:'#4f8cff'},\n    {id:'storage', label:'Storage', x:550, y:120, r:26, color:'#4f8cff'},\n    {id:'database', label:'Database', x:600, y:260, r:24, color:'#4f8cff'},\n    {id:'terraform', label:'Terraform', x:520, y:360, r:24, color:'#e8a33d'},\n    {id:'vault', label:'Vault', x:100, y:260, r:24, color:'#3ec28f'},\n    {id:'cloudguard', label:'Cloud Guard', x:150, y:360, r:26, color:'#3ec28f'},\n    {id:'monitoring', label:'Monitoring', x:350, y:390, r:24, color:'#9096a2'},\n    {id:'logging', label:'Logging', x:250, y:390, r:22, color:'#9096a2'},\n    {id:'budgets', label:'Budgets', x:60, y:340, r:20, color:'#e8a33d'},\n    {id:'dr', label:'DR', x:600, y:340, r:20, color:'#3ec28f'},\n    {id:'security', label:'Security Zones', x:450, y:60, r:24, color:'#3ec28f'},\n    {id:'governance', label:'Governance', x:230, y:180, r:24, color:'#c74634'},\n  ];\n  const edges = [['iam','networking'],['iam','compute'],['iam','storage'],['iam','database'],['iam','vault'],['iam','governance'],['iam','cloudguard'],['networking','compute'],['compute','storage'],['compute','monitoring'],['storage','dr'],['database','dr'],['terraform','compute'],['terraform','networking'],['vault','database'],['cloudguard','security'],['monitoring','logging'],['budgets','governance'],['security','networking']];\n  let svgStr = edges.map(([a,b])=>{\n    const na = nodes.find(n=>n.id===a), nb = nodes.find(n=>n.id===b);\n    return `<line x1=\"${na.x}\" y1=\"${na.y}\" x2=\"${nb.x}\" y2=\"${nb.y}\" stroke=\"var(--border-strong)\" stroke-width=\"1\"/>`;\n  }).join('');\n  svgStr += nodes.map(n=>`\n    <g class=\"kmap-node\" data-node=\"${n.id}\">\n      <circle cx=\"${n.x}\" cy=\"${n.y}\" r=\"${n.r}\" fill=\"${n.color}22\" stroke=\"${n.color}\" stroke-width=\"1.5\"/>\n      <text x=\"${n.x}\" y=\"${n.y+4}\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--text-1)\" font-family=\"sans-serif\">${n.label}</text>\n    </g>`).join('');\n  svg.innerHTML = svgStr;\n\n  const info = {\n    iam: {dep:'None \u2014 the foundation everything else builds on', rel:'Every service in this map', obj:'Compartments, Policies, Groups, Dynamic Groups, Federation', bp:'Least privilege, scoped policies per compartment', mistake:'Granting \"manage all-resources\" broadly instead of scoping per resource-family'},\n    networking: {dep:'IAM (policies to manage it)', rel:'Compute, Security Zones, Terraform', obj:'VCN, Subnets, Gateways, Security Lists/NSGs, Routing', bp:'Public/private subnet separation, least-exposure gateways', mistake:'Missing route rule after adding a new gateway'},\n    compute: {dep:'IAM, Networking (VNIC/subnet)', rel:'Storage, Monitoring, Terraform', obj:'Shapes, Images, cloud-init, Instance Metadata', bp:'Right-size based on real utilization, not guesses', mistake:'Launching in the wrong subnet type for the workload'},\n    storage: {dep:'IAM, Vault (optional encryption)', rel:'Compute, DR, Database', obj:'Object/Block/File/Archive tiers', bp:'Lifecycle policies to auto-tier aging data', mistake:'Leaving a bucket public by default'},\n    database: {dep:'Networking, Storage, Vault', rel:'DR, IAM', obj:'HA architecture, backup, TDE', bp:'Test restores regularly, not just configure backups', mistake:'Assuming a backup policy alone satisfies DR requirements'},\n    terraform: {dep:'IAM (to authenticate), Networking/Compute (to provision)', rel:'Resource Manager, all provisioned services', obj:'State management, drift detection, Resource Manager stacks', bp:'Never make manual Console changes to Terraform-managed resources', mistake:'Manual Console edits causing undetected state drift'},\n    vault: {dep:'IAM', rel:'Storage, Database, Secrets, Compute (via app integration)', obj:'MEK/DEK, HSM, key rotation, secrets versioning', bp:'HSM-protected keys for regulated workloads', mistake:'Rotating a secret without updating the actual credential it represents'},\n    cloudguard: {dep:'IAM, Networking, Compute', rel:'Security Zones, Logging', obj:'Detectors, Responders, Problem lifecycle', bp:'Enable at the tenancy root for consistent coverage', mistake:'Assuming detection replaces prevention (Security Zones)'},\n    monitoring: {dep:'Compute, Networking, all services', rel:'Logging, Notifications, Alarms', obj:'MQL, Alarms, Capacity Planning', bp:'Alarm on symptoms customers feel, not just raw metrics', mistake:'An alarm configured but its notification topic has no confirmed subscription'},\n    logging: {dep:'All services', rel:'Monitoring, Audit, Service Connector Hub', obj:'Service/Custom/Audit logs', bp:'Centralize via Service Connector Hub for multi-service correlation', mistake:'Logging disabled on a compartment that later needs incident forensics'},\n    budgets: {dep:'IAM, Governance', rel:'Cost Analysis, Governance', obj:'Alert thresholds, forecast', bp:'Budgets alert, they don\\'t hard-stop \u2014 pair with automation if a hard stop is needed', mistake:'Assuming a budget prevents overspend automatically'},\n    dr: {dep:'Storage, Database, Networking', rel:'Backup, Vault replication', obj:'RPO/RTO, failover testing', bp:'Test failover for real, on a schedule', mistake:'Documenting a DR plan that has never actually been executed'},\n    security: {dep:'Networking, IAM', rel:'Cloud Guard, Compliance', obj:'Hard-blocking non-compliant configurations', bp:'Apply to production compartments as a guardrail', mistake:'Assuming Security Zones replace the need for Cloud Guard'},\n    governance: {dep:'IAM', rel:'Budgets, Tagging, Org Management', obj:'Compartment design, tagging strategy, quotas', bp:'Design compartments around a single dominant axis (env or team)', mistake:'Deeply nested compartments that make policy management harder, not easier'},\n  };\n  const detail = document.getElementById('kmap-detail');\n  svg.querySelectorAll('.kmap-node').forEach(g=>{\n    g.addEventListener('click', ()=>{\n      svg.querySelectorAll('.kmap-node').forEach(x=>x.classList.remove('active')); g.classList.add('active');\n      const i = info[g.dataset.node];\n      detail.innerHTML = `<strong>Dependencies:</strong> ${i.dep}<br><strong>Related services:</strong> ${i.rel}<br><strong>Exam objectives:</strong> ${i.obj}<br><strong>Best practice:</strong> ${i.bp}<br><strong>Common mistake:</strong> ${i.mistake}`;\n    });\n  });\n}\n\n;\n\n/* ---------- oracle skill check ---------- */\nfunction initSkillCheck(){\n  const btns = document.querySelectorAll('#sc-type-btns .chip-btn'); if(!btns.length) return;\n  const bank = {\n    conceptual: [\n      {q:'Which NIST characteristic best describes automatic scale-up/down based on demand?', o:['Resource pooling','Elasticity','Measured service','Broad network access'], c:1, hint:'Think about what changes automatically without a person acting.', domain:'IAM & Governance'},\n      {q:'What does the \"D\" in DEK stand for in OCI Vault\\'s envelope encryption?', o:['Default','Data','Domain','Delegated'], c:1, hint:'It\\'s the key that actually encrypts your data.', domain:'Security & Vault'},\n    ],\n    applied: [\n      {q:'A private subnet instance needs outbound internet access only. Which gateway do you attach?', o:['Internet Gateway','NAT Gateway','Service Gateway','Dynamic Routing Gateway'], c:1, hint:'\"Outbound only\" is the key phrase.', domain:'Networking'},\n      {q:'You need to grant a team manage access to instances but not the ability to delete boot volumes independently. What\\'s the simplest correct approach?', o:['Grant \"manage instance-family\" which covers this', 'Grant \"manage instances\" but \"read volume-family\"','Grant \"manage all-resources\"','This isn\\'t possible in OCI'], c:0, hint:'Think about what a resource-family bundle actually includes.', domain:'IAM & Governance'},\n    ],\n    architecture: [\n      {q:'For a 3-tier web app needing DR across regions, which combination is most appropriate?', o:['Single region, single AD','Multi-AD in one region, cross-region Vault/data replication for DR','No replication needed if backups exist','Cross-region only, skip multi-AD'], c:1, hint:'You need both local (AD) and regional (cross-region) resilience.', domain:'HA/DR'},\n      {q:'A banking workload requires FIPS 140-2 Level 3 keys. Which Vault configuration is correct?', o:['Software Protected','HSM Protected','Any protection mode works','Vault doesn\\'t support this'], c:1, hint:'FIPS 140-2 Level 3 specifically implies hardware.', domain:'Security & Vault'},\n    ],\n    troubleshooting: [\n      {q:'terraform apply fails with a CIDR overlap error that wasn\\'t present in the last plan. Most likely cause?', o:['A bug in Terraform','Manual Console changes causing state drift', 'Insufficient IAM permissions','Wrong region configured'], c:1, hint:'Something changed outside of Terraform\\'s knowledge.', domain:'Terraform'},\n      {q:'A load balancer shows all backends healthy, but customers see intermittent 502s. What should you investigate?', o:['The health check config only','Whether backends are failing under real request load despite passing periodic health checks', 'The client\\'s browser','DNS caching only'], c:1, hint:'Health checks sample; they don\\'t see every real request.', domain:'Monitoring & Troubleshooting'},\n    ]\n  };\n  let currentType = 'conceptual', currentIdx = 0;\n  const area = document.getElementById('sc-question-area');\n  const hintBox = document.getElementById('sc-hint-box');\n  function render(){\n    const item = bank[currentType][currentIdx % bank[currentType].length];\n    hintBox.style.display='none';\n    area.innerHTML = `<span class=\"sc-type-badge\">${currentType}</span>\n      <p style=\"font-size:14.5px; font-weight:600;\">${item.q}</p>\n      <div class=\"quiz-opts\">${item.o.map((opt,oi)=>`<label class=\"quiz-opt\"><input type=\"radio\" name=\"scq\" value=\"${oi}\"> ${opt}</label>`).join('')}</div>`;\n    area.querySelectorAll('.quiz-opt').forEach((label,oi)=>{\n      label.addEventListener('click', ()=>{\n        area.querySelectorAll('.quiz-opt').forEach(l=>l.classList.remove('correct','incorrect'));\n        if(oi===item.c) label.classList.add('correct'); else label.classList.add('incorrect');\n        recordAnswer(item.domain, oi===item.c);\n      }, {once:true});\n    });\n    hintBox.textContent = '\ud83d\udca1 ' + item.hint;\n  }\n  btns.forEach(b=> b.addEventListener('click', ()=>{ btns.forEach(x=>x.classList.remove('active')); b.classList.add('active'); currentType=b.dataset.sctype; currentIdx=0; render(); }));\n  document.getElementById('sc-hint-btn').addEventListener('click', ()=>{ hintBox.style.display='block'; });\n  document.getElementById('sc-next-btn').addEventListener('click', ()=>{ currentIdx++; render(); });\n  render();\n}\n\n/* ---------- architecture discussion center ---------- */\nfunction initArchDiscussion(){\n  const btns = document.querySelectorAll('#archdisc-industry-btns .chip-btn'); if(!btns.length) return;\n  const scenarios = {\n    banking: 'Proposed: single-region deployment, shared Vault, public bucket for statements (with signed URLs), manual patching.',\n    healthcare: 'Proposed: multi-AD deployment, HSM Vault, Security Zone on PHI compartment, quarterly manual DR test.',\n    retail: 'Proposed: autoscaling web tier, no NSGs (Security Lists only), Object Storage for product images, single Fault Domain for DB.',\n    manufacturing: 'Proposed: Site-to-Site VPN to factory floor, single tunnel (no redundancy), Cloud Guard disabled on IoT compartment.',\n    government: 'Proposed: dedicated tenancy, strict Security Zones, manual compliance report generation, no budget alerts configured.',\n    saas: 'Proposed: multi-tenant architecture, shared compute pool, per-customer compartments, Terraform-managed, weekly cost review.'\n  };\n  const dims = ['Security','Cost','Availability','Performance','Compliance','Operations'];\n  const evalGrid = document.getElementById('archdisc-eval-grid');\n  evalGrid.innerHTML = dims.map(d=>`<div class=\"arch-eval-item\">${d}<select class=\"mini-input\" data-dim=\"${d}\"><option>Poor</option><option>Fair</option><option selected>Good</option><option>Excellent</option></select></div>`).join('');\n  const expertReviews = {\n    banking: 'Expert review: \u26a0 Single-region is a DR gap for banking-grade availability requirements. \u26a0 A public bucket, even with signed URLs, is unnecessary exposure \u2014 use pre-authenticated requests scoped narrowly instead. \u2713 Shared Vault is acceptable at this scale.',\n    healthcare: '\u2713 Multi-AD and HSM Vault are appropriate for PHI. \u2713 Security Zone on the PHI compartment is a strong control. \u26a0 Quarterly manual DR testing is good cadence, but \"manual\" risks inconsistency \u2014 consider scripting the failover runbook.',\n    retail: '\u26a0 No NSGs means all security rules are subnet-wide, less granular than ideal for a multi-tier app. \u26a0 Single Fault Domain for the DB is a real availability risk \u2014 spread across FDs at minimum. \u2713 Autoscaling web tier is well-suited to retail traffic patterns.',\n    manufacturing: '\u26a0 A single VPN tunnel has no redundancy \u2014 one CPE hiccup takes down factory connectivity entirely. \u26a0 Cloud Guard disabled on the IoT compartment is a meaningful blind spot precisely where unusual device behavior needs detection.',\n    government: '\u2713 Dedicated tenancy and strict Security Zones fit government requirements well. \u26a0 Manual compliance reporting doesn\\'t scale and risks becoming stale \u2014 automate evidence collection. \u26a0 No budget alerts risks a surprise overrun going unnoticed.',\n    saas: '\u2713 Per-customer compartments give good tenant isolation. \u2713 Terraform-managed and weekly cost review are strong operational habits. \u26a0 A shared compute pool needs careful noisy-neighbor mitigation (e.g. resource limits) to protect SLAs.'\n  };\n  function render(ind){ document.getElementById('archdisc-scenario').textContent = scenarios[ind]; document.getElementById('archdisc-expert').style.display='none'; }\n  btns.forEach(b=> b.addEventListener('click', ()=>{ btns.forEach(x=>x.classList.remove('active')); b.classList.add('active'); render(b.dataset.adind); }));\n  render('banking');\n  document.getElementById('archdisc-review').addEventListener('click', ()=>{\n    const active = document.querySelector('#archdisc-industry-btns .chip-btn.active').dataset.adind;\n    const out = document.getElementById('archdisc-expert'); out.style.display='block';\n    out.textContent = expertReviews[active];\n  });\n}\n\n/* ---------- exam question pattern explorer demo ---------- */\nfunction initPatternExplorer(){\n  const btn = document.getElementById('pattern-demo-check'); if(!btn) return;\n  btn.addEventListener('click', ()=>{\n    const sel = document.querySelector('input[name=\"patterndemo\"]:checked');\n    const fb = document.getElementById('pattern-demo-result');\n    document.querySelectorAll('#pattern-demo-opts .quiz-opt').forEach(o=>o.classList.remove('correct','incorrect'));\n    if(!sel){ fb.textContent='Pick an option first.'; return; }\n    const parent = sel.closest('.quiz-opt');\n    if(sel.value==='right'){ parent.classList.add('correct'); fb.textContent='\u2713 Correct \u2014 \"MOST cost-effective\" + \"rarely accessed\" + long retention is the exact profile Archive Storage is built for.'; fb.style.color='var(--green)'; }\n    else { parent.classList.add('incorrect'); fb.textContent='\u2717 Re-read the keywords: \"MOST cost-effective\" and \"rarely accessed\" together point away from Standard tier or Block Volume.'; fb.style.color='var(--red-bright)'; }\n  });\n}\n\n;\n\n/* ============================================================\n   MASTER QUESTION BANK \u2014 used by Practice Sets 1-4 and the\n   Mock Exam engine. 48 real questions, tagged by set/domain/\n   difficulty, each with explanation + doc reference + mistake.\n   ============================================================ */\nconst QBANK = [\n// SET 1 \u2014 Cloud Foundations, IAM, Security, Governance, Cost (12)\n{set:1, domain:'IAM & Governance', difficulty:'easy', q:'What does the policy verb \"manage\" include that \"use\" does not?', o:['Read access','Create and delete operations','List operations','Nothing, they are identical'], c:1, e:'\"manage\" is the broadest verb \u2014 it includes create/delete lifecycle actions that \"use\" does not.', ref:'IAM Policy Reference \u2014 Verbs', mistake:'Assuming \"use\" allows deleting a resource.'},\n{set:1, domain:'IAM & Governance', difficulty:'medium', q:'A policy is attached to the Production compartment. Does it apply to a child compartment \"Production/Finance\"?', o:['No, policies never inherit','Yes, policies are inherited by child compartments by default','Only if explicitly copied','Only for read verbs'], c:1, e:'Policies attached to a parent compartment are inherited by all children unless scoped narrower.', ref:'IAM Policies \u2014 Inheritance', mistake:'Re-writing the same policy at every child compartment unnecessarily.'},\n{set:1, domain:'Cost', difficulty:'easy', q:'What is the main functional difference between a Budget and a Quota?', o:['They are the same thing','A Budget alerts on spend; a Quota caps resource counts','A Quota alerts on spend; a Budget caps resource counts','Budgets require Oracle support tickets'], c:1, e:'Budgets are financial alerting; Quotas are resource-count governance \u2014 different dimensions entirely.', ref:'Cost Management \u2014 Budgets vs Quotas', mistake:'Expecting a Budget to hard-stop spend automatically.'},\n{set:1, domain:'Cost', difficulty:'medium', q:'Which OCI free offering persists indefinitely, beyond the 30-day trial?', o:['30-Day Free Trial credits','Always Free resources','Premium support','Enterprise licensing'], c:1, e:'Always Free resources remain available indefinitely, separate from the time-boxed trial credits.', ref:'OCI Free Tier documentation', mistake:'Assuming all free resources expire after 30 days.'},\n{set:1, domain:'Security & Vault', difficulty:'medium', q:'What is the key difference between Cloud Guard and Security Zones?', o:['They are identical features','Cloud Guard detects and responds after the fact; Security Zones block non-compliant actions at request time', 'Security Zones only work with storage','Cloud Guard requires a paid add-on'], c:1, e:'One is preventive (Security Zones), the other is detective/responsive (Cloud Guard) \u2014 complementary, not redundant.', ref:'Cloud Guard & Security Zones overview', mistake:'Assuming enabling one makes the other unnecessary.'},\n{set:1, domain:'IAM & Governance', difficulty:'hard', q:'A Dynamic Group\\'s matching rule is scoped too broadly, granting excess instances access. What principle was violated?', o:['Defense in depth','Least privilege','Zero trust','Elasticity'], c:1, e:'Granting more access than needed \u2014 even accidentally via a broad matching rule \u2014 is a least-privilege violation.', ref:'Dynamic Groups \u2014 Matching Rules', mistake:'Writing a matching rule scoped to an entire compartment when only specific instances need access.'},\n{set:1, domain:'Compute & Storage', difficulty:'easy', q:'Which OCI service type is best for HTTP-accessible, unstructured data at massive scale?', o:['Block Storage','Object Storage','File Storage','Local NVMe'], c:1, e:'Object Storage is purpose-built for HTTP-native, unlimited-scale unstructured data.', ref:'Storage Services overview', mistake:'Using Block Storage for use cases needing broad HTTP access.'},\n{set:1, domain:'Networking', difficulty:'medium', q:'What is required for a public subnet instance to actually be reachable from the internet, beyond attaching an Internet Gateway?', o:['Nothing else is needed','A route table rule to the IGW and a Security List/NSG rule allowing the traffic', 'A NAT Gateway as well','A Service Gateway as well'], c:1, e:'An attached IGW alone is not sufficient \u2014 routing and security rules must also permit the traffic.', ref:'VCN Networking \u2014 Internet Gateway', mistake:'Assuming attaching a gateway alone grants connectivity.'},\n{set:1, domain:'IAM & Governance', difficulty:'medium', q:'What does \"Organization Management\" primarily provide across linked tenancies?', o:['Shared IAM users','Centralized billing while keeping IAM fully isolated','Merged compartments','Free credits'], c:1, e:'It consolidates billing/governance oversight without merging each tenancy\\'s IAM.', ref:'Organization Management overview', mistake:'Assuming linked tenancies share user accounts.'},\n{set:1, domain:'Cost', difficulty:'hard', q:'A workload has a stable, predictable 70% baseline usage with a volatile 30% spike component. What\\'s the FinOps-recommended approach?', o:['Commit 100% to a multi-year plan','Commit only the stable ~70% baseline, keep the volatile portion Pay-As-You-Go','Use no commitments at all','Commit only the volatile 30%'], c:1, e:'Commitment discounts are best applied to predictable baseline usage, leaving volatile usage flexible.', ref:'FinOps \u2014 Commitment Discounts', mistake:'Committing spend for unpredictable, spiky usage.'},\n{set:1, domain:'Security & Vault', difficulty:'medium', q:'Why is \"chmod 777\" considered a common security mistake?', o:['It slows performance','It makes a file world-writable \u2014 any local user or compromised process can modify it', 'It disables encryption','It is only a cosmetic issue'], c:1, e:'World-writable permissions let any account (or malicious code with any execution) overwrite the file.', ref:'Linux Permissions \u2014 Common Mistakes', mistake:'Using 777 as a quick fix for permission errors.'},\n{set:1, domain:'IAM & Governance', difficulty:'easy', q:'What is the root compartment in an OCI tenancy?', o:['A specially created compartment','The tenancy itself','Only used for billing','Deleted after setup'], c:1, e:'The root compartment IS the tenancy \u2014 every other compartment nests beneath it.', ref:'Compartments overview', mistake:'Thinking the root compartment must be manually created.'},\n\n// SET 2 \u2014 Terraform, Networking, VCN, Compute, Storage (12)\n{set:2, domain:'Terraform', difficulty:'medium', q:'A terraform apply fails due to a resource that was manually deleted in the Console. What is this called?', o:['A syntax error','State drift','A provider bug','A quota violation'], c:1, e:'When real infrastructure diverges from Terraform\\'s recorded state, that\\'s drift.', ref:'Terraform State Management', mistake:'Making manual Console changes to Terraform-managed resources.'},\n{set:2, domain:'Terraform', difficulty:'easy', q:'What does OCI Resource Manager provide on top of open-source Terraform?', o:['A different HCL syntax','A managed service for running Terraform stacks with state storage and drift detection','Nothing, it is identical','Only local execution'], c:1, e:'Resource Manager is Oracle\\'s managed Terraform execution and state-storage service.', ref:'Resource Manager overview', mistake:'Assuming Resource Manager requires a different IaC language.'},\n{set:2, domain:'Networking', difficulty:'medium', q:'What is the valid CIDR prefix range for an OCI VCN?', o:['/8 to /24','/16 to /30','/24 to /32','Any prefix is valid'], c:1, e:'OCI requires VCN CIDR blocks between /16 and /30.', ref:'VCN CIDR requirements', mistake:'Trying to create a VCN with a /8 or /32 CIDR.'},\n{set:2, domain:'Networking', difficulty:'hard', q:'Two route rules match a destination: a /16 and a /24. Which wins?', o:['The /16, since broader rules take priority','The /24, via longest-prefix-match','Both apply simultaneously','Neither \u2014 this is a conflict error'], c:1, e:'OCI route tables use longest-prefix-match; the more specific /24 wins.', ref:'Route Tables \u2014 Longest Prefix Match', mistake:'Assuming the first-created rule always wins.'},\n{set:2, domain:'Networking', difficulty:'medium', q:'Which gateway lets a private subnet reach Object Storage without traversing the public internet?', o:['NAT Gateway','Internet Gateway','Service Gateway','Local Peering Gateway'], c:2, e:'Service Gateway provides private access specifically to OCI public services.', ref:'Service Gateway overview', mistake:'Using a NAT Gateway when Service Gateway is the more secure, appropriate fit.'},\n{set:2, domain:'Networking', difficulty:'easy', q:'What is the primary difference between Security Lists and NSGs?', o:['NSGs are stateless','Security Lists apply subnet-wide; NSGs scope to specific VNICs','They are functionally identical','Security Lists work only with Compute'], c:1, e:'NSGs let you scope rules to individual VNICs rather than an entire subnet.', ref:'Network Security \u2014 Security Lists vs NSGs', mistake:'Trying to scope a rule to one instance using only a Security List.'},\n{set:2, domain:'Compute & Storage', difficulty:'medium', q:'What runs during an instance\\'s first boot to apply launch-time configuration?', o:['systemd only','cloud-init','A manual script the admin must run','The hypervisor'], c:1, e:'cloud-init executes once on first boot to configure packages, users, and run commands.', ref:'Compute \u2014 cloud-init overview', mistake:'Expecting cloud-init to re-run on every subsequent boot.'},\n{set:2, domain:'Compute & Storage', difficulty:'medium', q:'A right-sizing recommendation to downsize a VM should be based on:', o:['Guesswork','Actual observed utilization metrics','The most expensive available shape','Random sampling'], c:1, e:'Utilization data is the only reliable basis for a right-sizing decision.', ref:'Cost Optimization \u2014 Right Sizing', mistake:'Right-sizing based on assumptions rather than metrics.'},\n{set:2, domain:'Compute & Storage', difficulty:'hard', q:'A block volume attach fails. What is a common root cause?', o:['The volume and instance are in different Availability Domains','The volume is too small','The instance has too much RAM','The compartment has too many tags'], c:0, e:'Block volumes can only attach to instances within the same Availability Domain.', ref:'Block Volume \u2014 Attachment Requirements', mistake:'Assuming any instance in the region can attach any volume.'},\n{set:2, domain:'Networking', difficulty:'medium', q:'Instances in Fault Domain 1 all fail simultaneously during a rack-level power event. What design mistake caused the widest blast radius?', o:['Using too many Availability Domains','Placing all redundant instances in the same Fault Domain','Enabling Cloud Guard','Using Object Storage'], c:1, e:'Instances sharing a Fault Domain share power/hardware \u2014 a single failure can take all of them down together.', ref:'Fault Domains overview', mistake:'Not spreading redundant instances across Fault Domains.'},\n{set:2, domain:'Terraform', difficulty:'hard', q:'What should you run before terraform apply if you suspect state drift?', o:['terraform destroy','terraform plan (or refresh) to detect drift first','terraform init only','Nothing, apply handles it automatically'], c:1, e:'terraform plan (with refresh) surfaces drift before you commit to changes.', ref:'Terraform \u2014 Drift Detection', mistake:'Applying blind without reviewing plan output first.'},\n{set:2, domain:'Compute & Storage', difficulty:'easy', q:'Which storage type provides a shared NFS filesystem mountable by multiple instances at once?', o:['Block Storage','Object Storage','File Storage','Boot Volume'], c:2, e:'File Storage is the NFS-based, concurrently-shareable storage service.', ref:'File Storage overview', mistake:'Trying to mount a Block Volume on multiple instances simultaneously.'},\n\n// SET 3 \u2014 Vault, Encryption, KMS, HA, DR (12)\n{set:3, domain:'Security & Vault', difficulty:'medium', q:'In OCI Vault\\'s envelope encryption, what does the Master Encryption Key (MEK) actually encrypt?', o:['Your data directly','A Data Encryption Key (DEK), which then encrypts your data','Nothing, it only authenticates','The TLS certificate'], c:1, e:'The MEK wraps a DEK; the DEK does the bulk data encryption \u2014 this is envelope encryption.', ref:'OCI Vault \u2014 Envelope Encryption', mistake:'Assuming the MEK directly encrypts large data volumes.'},\n{set:3, domain:'Security & Vault', difficulty:'easy', q:'Which key protection mode provides FIPS 140-2 Level 3 hardware-backed security?', o:['Software Protected','HSM Protected','Virtual Private Vault only','None of these'], c:1, e:'HSM Protected mode uses validated tamper-resistant hardware.', ref:'Vault \u2014 Key Protection Modes', mistake:'Choosing Software Protected for a workload with hardware-backed compliance requirements.'},\n{set:3, domain:'Security & Vault', difficulty:'medium', q:'Scheduling a Vault key for deletion results in:', o:['Immediate permanent deletion','A mandatory 7-30 day waiting period before permanent deletion','The key being disabled forever with no recovery','No effect'], c:1, e:'The waiting period exists specifically so an accidental deletion can be cancelled.', ref:'Vault \u2014 Key Deletion', mistake:'Panicking instead of simply cancelling the scheduled deletion.'},\n{set:3, domain:'Security & Vault', difficulty:'hard', q:'An application throws authentication errors immediately after a secret rotation. Most likely cause?', o:['The Vault service is down','The actual credential (e.g. database password) wasn\\'t updated to match the new secret version','The network changed','TLS certificates expired'], c:1, e:'Rotating the secret record doesn\\'t automatically change the real system\\'s credential unless automated together.', ref:'Secrets Management \u2014 Rotation', mistake:'Rotating a secret without also updating the underlying credential.'},\n{set:3, domain:'HA/DR', difficulty:'easy', q:'What does RPO (Recovery Point Objective) measure?', o:['How long recovery takes','How much data loss is acceptable, measured in time', 'The cost of a DR solution', 'The number of backup copies'], c:1, e:'RPO defines the maximum acceptable data loss window, measured as time since the last good copy.', ref:'Disaster Recovery \u2014 RPO/RTO', mistake:'Confusing RPO (data loss) with RTO (downtime).'},\n{set:3, domain:'HA/DR', difficulty:'medium', q:'What does RTO (Recovery Time Objective) measure?', o:['Acceptable data loss','The maximum acceptable time to restore service after a failure', 'Encryption key strength', 'Number of Availability Domains'], c:1, e:'RTO is about downtime duration, not data loss.', ref:'Disaster Recovery \u2014 RPO/RTO', mistake:'Designing only for RPO while ignoring RTO requirements.'},\n{set:3, domain:'HA/DR', difficulty:'hard', q:'A DR failover test to a replica region fails because the application can\\'t start. Most likely cause?', o:['The replica region doesn\\'t support compute','Configuration drift \u2014 the replica wasn\\'t granted the same IAM policies/config as primary', 'DR tests always fail on the first attempt', 'The primary region is required for DR'], c:1, e:'Replica environments commonly drift from primary unless kept in sync deliberately \u2014 exactly why real tests matter.', ref:'DR \u2014 Failover Testing', mistake:'Documenting a DR plan without ever executing a real failover test.'},\n{set:3, domain:'Security & Vault', difficulty:'medium', q:'Cross-region Vault replication primarily protects against:', o:['Slow application performance','An entire region becoming unavailable', 'Weak passwords', 'Expired certificates'], c:1, e:'Replication ensures keys remain usable if the primary region fails.', ref:'Vault \u2014 Cross-Region Replication', mistake:'Assuming a single-region Vault is sufficient for DR-critical encryption.'},\n{set:3, domain:'HA/DR', difficulty:'medium', q:'For a database requiring high availability within a single region, what is the minimum recommended spread?', o:['Single Availability Domain, single Fault Domain','Multiple Fault Domains (or ADs where available)', 'A single instance is sufficient', 'Object Storage replaces the need for HA'], c:1, e:'Spreading across Fault Domains (or ADs) avoids a single rack/power failure taking down the whole database tier.', ref:'High Availability Design Patterns', mistake:'Deploying all HA replicas in the same Fault Domain.'},\n{set:3, domain:'Security & Vault', difficulty:'easy', q:'What is a Digital Signature created with?', o:['The signer\\'s public key','The signer\\'s private key', 'A shared symmetric key', 'The recipient\\'s public key'], c:1, e:'Signing uses the private key; anyone can verify using the corresponding public key.', ref:'PKI \u2014 Digital Signatures', mistake:'Confusing which key signs vs which key verifies.'},\n{set:3, domain:'Security & Vault', difficulty:'hard', q:'A certificate chain fails validation despite a valid, unexpired leaf certificate. Likely cause?', o:['The Root CA changed algorithms','A missing Intermediate CA certificate in the server configuration', 'The private key expired', 'DNS is misconfigured'], c:1, e:'Browsers verify the full chain; a missing intermediate breaks the trust path even with a valid leaf.', ref:'PKI \u2014 Chain of Trust', mistake:'Installing only the leaf certificate without the intermediate.'},\n{set:3, domain:'HA/DR', difficulty:'medium', q:'What validates that a backup strategy actually works, beyond having a backup policy configured?', o:['Nothing further is needed','A periodic test restore, verified end to end', 'Encrypting the backup', 'Increasing backup frequency'], c:1, e:'A configured backup policy proves nothing about recoverability until a restore is actually tested.', ref:'Backup Validation Best Practices', mistake:'Treating \"backups are configured\" as equivalent to \"backups work.\"'},\n\n// SET 4 \u2014 Troubleshooting, Monitoring, Logging, Audit, Governance (12)\n{set:4, domain:'Monitoring & Troubleshooting', difficulty:'easy', q:'In the 6-step troubleshooting methodology, what comes immediately after \"Resolve\"?', o:['Prevent','Validate', 'Identify', 'Isolate'], c:1, e:'You must Validate the fix actually resolved the issue before moving to Prevent.', ref:'Troubleshooting Methodology', mistake:'Closing an incident without validating the fix worked for the user.'},\n{set:4, domain:'Monitoring & Troubleshooting', difficulty:'medium', q:'SSH shows \"Connection timed out\" rather than \"Permission denied.\" This most likely points to:', o:['A wrong SSH key','A network-level block (NSG, Security List, or route)', 'A wrong username', 'A cloud-init failure'], c:1, e:'A timeout (vs explicit rejection) is characteristic of packets being silently dropped at the network layer.', ref:'SSH Troubleshooting Guide', mistake:'Assuming every SSH failure is a key/credential problem.'},\n{set:4, domain:'Monitoring & Troubleshooting', difficulty:'medium', q:'A load balancer returns 503 Service Unavailable. This most directly means:', o:['The backend took too long to respond','No healthy backends are currently available in the backend set', 'The client sent malformed data', 'The SSL certificate expired'], c:1, e:'503 specifically indicates the LB has no healthy backend to route to.', ref:'Load Balancer \u2014 HTTP Status Codes', mistake:'Confusing 503 (no healthy backend) with 504 (backend too slow).'},\n{set:4, domain:'Monitoring & Troubleshooting', difficulty:'hard', q:'Asymmetric routing commonly breaks connectivity because:', o:['It uses too much bandwidth','Stateful firewalls only recognize traffic traversing them in both directions and drop the \"unrecognized\" return path', 'DNS caches become corrupted', 'It doubles latency only'], c:1, e:'A stateful firewall that only sees one direction of a flow treats the return traffic as unsolicited and drops it.', ref:'Networking \u2014 Asymmetric Routing', mistake:'Not verifying both directions of traffic traverse the same firewall/path.'},\n{set:4, domain:'Monitoring & Troubleshooting', difficulty:'medium', q:'What is Metric Query Language (MQL) primarily used for?', o:['Writing IAM policies','Querying and aggregating monitoring metrics for alarms and dashboards', 'Querying Object Storage contents', 'Writing Terraform modules'], c:1, e:'MQL is the query syntax behind OCI Monitoring\\'s metrics and alarms.', ref:'OCI Monitoring \u2014 MQL', mistake:'Confusing MQL with a general-purpose database query language.'},\n{set:4, domain:'IAM & Governance', difficulty:'medium', q:'Audit logs in OCI are best described as:', o:['Optional and rarely useful','An automatically recorded history of API calls across the tenancy, essential for compliance and forensics', 'Something you must configure from scratch', 'Only available for compute resources'], c:1, e:'Audit is automatically enabled tenancy-wide, recording API activity for compliance and investigation.', ref:'Audit Service overview', mistake:'Assuming Audit logging must be manually enabled per-service.'},\n{set:4, domain:'Monitoring & Troubleshooting', difficulty:'easy', q:'What is the purpose of Service Connector Hub?', o:['Load balancing traffic','Routing logs/metrics from a source service to a target (e.g. Streaming, Object Storage, another region)', 'Managing IAM policies', 'Creating VCNs'], c:1, e:'Service Connector Hub pipes logging/monitoring data between OCI services without custom glue code.', ref:'Service Connector Hub overview', mistake:'Building custom scripts to move logs when Service Connector Hub already does this natively.'},\n{set:4, domain:'Monitoring & Troubleshooting', difficulty:'medium', q:'An alarm is correctly configured and firing, but nobody was paged during an incident. Likely cause?', o:['The alarm threshold was wrong','The notification topic subscription was never confirmed', 'Monitoring was disabled tenancy-wide', 'The metric doesn\\'t exist'], c:1, e:'A common gap: the alarm fires correctly but its notification subscription (e.g. email/Slack) was never confirmed.', ref:'Notifications \u2014 Topic Subscriptions', mistake:'Assuming a configured alarm guarantees someone gets paged.'},\n{set:4, domain:'Cost', difficulty:'medium', q:'A budget alert fires at 90% of the monthly threshold. What happens automatically to further spend?', o:['Spend is capped at 90% automatically','Nothing \u2014 a notification is sent, but spend continues unless a human or automation acts', 'All resources are suspended', 'The tenancy is locked'], c:1, e:'Budgets are alerting mechanisms only, not automatic spending caps.', ref:'Budgets overview', mistake:'Assuming a budget threshold halts spend automatically.'},\n{set:4, domain:'IAM & Governance', difficulty:'hard', q:'A production outage investigation rules out compute, network, security, storage, and DNS \u2014 the load balancer shows all backends healthy. Where next?', o:['Nowhere, it must be a false alarm','The application layer itself (recent deploys, code, dependencies)', 'Re-check compute again', 'The physical data center'], c:1, e:'If traffic reaches healthy backends but the service still fails, the application layer is the remaining suspect.', ref:'Root Cause Analysis \u2014 Elimination', mistake:'Stopping the investigation once infrastructure looks healthy, without checking recent application deploys.'},\n{set:4, domain:'Monitoring & Troubleshooting', difficulty:'medium', q:'iostat shows a volume at 98% utilization with high write latency. What does this suggest?', o:['The volume is idle','The volume is I/O-saturated for its current performance tier', 'The instance has a memory leak', 'The network is misconfigured'], c:1, e:'High utilization plus high latency together point to the disk itself being the bottleneck.', ref:'Storage Performance Analysis', mistake:'Investigating network or compute first when disk metrics already point to storage.'},\n{set:4, domain:'IAM & Governance', difficulty:'easy', q:'A postmortem/incident report should always include:', o:['Only the timeline','Root cause plus both corrective AND preventive action', 'Only who was on call', 'Just a one-line summary'], c:1, e:'A complete postmortem addresses fixing the immediate problem AND preventing recurrence.', ref:'Incident Response \u2014 Postmortems', mistake:'Writing a postmortem with no preventive action, only a fix.'},\n];\n\n/* ---------- practice set renderer ---------- */\nfunction initQBank(){\n  for(let setNum=1; setNum<=4; setNum++){\n    const container = document.getElementById('qbank-set-'+setNum);\n    if(!container) continue;\n    const questions = QBANK.filter(q=>q.set===setNum);\n    container.innerHTML = questions.map((item,qi)=>`\n      <div class=\"qbank-card\" id=\"qb-${setNum}-${qi}\">\n        <span class=\"qbank-bookmark\" data-bm=\"${setNum}-${qi}\">\u2606</span>\n        <div class=\"qbank-meta\">\n          <span class=\"diff-${item.difficulty}\">${item.difficulty}</span>\n          <span>${item.domain}</span>\n        </div>\n        <p style=\"font-weight:600; font-size:14px;\">${qi+1}. ${item.q}</p>\n        <div class=\"quiz-opts\">${item.o.map((opt,oi)=>`<label class=\"quiz-opt\"><input type=\"radio\" name=\"qb-${setNum}-${qi}\" value=\"${oi}\"> ${opt}</label>`).join('')}</div>\n        <div class=\"quiz-explain\" id=\"qb-explain-${setNum}-${qi}\">${item.e}</div>\n        <div class=\"qbank-refnote\" id=\"qb-ref-${setNum}-${qi}\">\ud83d\udcd6 Reference: ${item.ref} &nbsp;\u00b7&nbsp; \u26a0 Common mistake: ${item.mistake}</div>\n      </div>`).join('');\n\n    container.querySelectorAll('.qbank-bookmark').forEach(bm=>{\n      bm.addEventListener('click', ()=>{ bm.textContent = bm.textContent==='\u2606' ? '\u2605' : '\u2606'; bm.style.color = bm.textContent==='\u2605' ? 'var(--red-bright)' : ''; });\n    });\n\n    questions.forEach((item,qi)=>{\n      const card = document.getElementById(`qb-${setNum}-${qi}`);\n      card.addEventListener('change', e=>{\n        if(card.dataset.answered) return;\n        card.dataset.answered = '1';\n        const chosen = parseInt(e.target.value);\n        card.querySelectorAll('.quiz-opt').forEach((o,oi)=>{ if(oi===item.c) o.classList.add('correct'); else if(oi===chosen) o.classList.add('incorrect'); });\n        card.querySelector('.quiz-explain').style.display='block';\n        document.getElementById(`qb-ref-${setNum}-${qi}`).classList.add('show');\n        recordAnswer(item.domain, chosen===item.c);\n        const answeredCount = container.querySelectorAll('[data-answered]').length;\n        document.getElementById('qb'+setNum+'-progress').textContent = `${answeredCount}/${questions.length} answered`;\n      });\n    });\n  }\n}\n\n;\n\n/* ---------- timed mock exam engine ---------- */\nfunction initMockExam(){\n  const lenCards = document.querySelectorAll('#exam-len-grid .exam-len-card'); if(!lenCards.length) return;\n  let selectedLen = 30;\n  lenCards.forEach(c=> c.addEventListener('click', ()=>{ lenCards.forEach(x=>x.classList.remove('selected')); c.classList.add('selected'); selectedLen = parseInt(c.dataset.len); }));\n  lenCards[0].classList.add('selected');\n\n  let examQuestions = [], examAnswers = [], examFlags = [], currentQ = 0, timerInterval = null, secondsLeft = 0, paused = false, negativeMarking = false;\n\n  function shuffle(arr){ const a=[...arr]; for(let i=a.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); [a[i],a[j]]=[a[j],a[i]]; } return a; }\n\n  function buildExam(len){\n    let pool = shuffle(QBANK);\n    let list = [];\n    while(list.length < len){ list = list.concat(shuffle(QBANK)); }\n    return list.slice(0, len);\n  }\n\n  document.getElementById('exam-start-btn').addEventListener('click', ()=>{\n    negativeMarking = document.getElementById('exam-negative-toggle').checked;\n    examQuestions = buildExam(selectedLen);\n    examAnswers = new Array(examQuestions.length).fill(null);\n    examFlags = new Array(examQuestions.length).fill(false);\n    currentQ = 0;\n    secondsLeft = selectedLen * 50; // ~50s/question budget\n    paused = false;\n    document.getElementById('exam-setup-panel').style.display='none';\n    document.getElementById('exam-results-panel').style.display='none';\n    document.getElementById('exam-run-panel').style.display='block';\n    renderNavGrid(); renderQuestion(); startTimer();\n  });\n\n  function startTimer(){\n    clearInterval(timerInterval);\n    timerInterval = setInterval(()=>{\n      if(paused) return;\n      secondsLeft--;\n      updateTimerDisplay();\n      if(secondsLeft<=0){ clearInterval(timerInterval); submitExam(); }\n    }, 1000);\n  }\n  function updateTimerDisplay(){\n    const m = Math.floor(Math.max(0,secondsLeft)/60), s = Math.max(0,secondsLeft)%60;\n    document.getElementById('exam-timer').textContent = `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;\n  }\n  updateTimerDisplay();\n\n  document.getElementById('exam-pause-btn').addEventListener('click', function(){\n    paused = !paused; this.textContent = paused ? '\u25b6 Resume' : '\u23f8 Pause';\n  });\n\n  function renderNavGrid(){\n    const grid = document.getElementById('exam-nav-grid');\n    grid.innerHTML = examQuestions.map((q,i)=> `<div class=\"exam-nav-dot ${examAnswers[i]!==null?'answered':''} ${examFlags[i]?'flagged':''} ${i===currentQ?'current':''}\" data-navq=\"${i}\">${i+1}</div>`).join('');\n    grid.querySelectorAll('.exam-nav-dot').forEach(dot=> dot.addEventListener('click', ()=>{ currentQ = parseInt(dot.dataset.navq); renderQuestion(); renderNavGrid(); }));\n  }\n\n  function renderQuestion(){\n    const item = examQuestions[currentQ];\n    const area = document.getElementById('exam-question-area');\n    area.innerHTML = `<div class=\"qbank-meta\"><span class=\"diff-${item.difficulty}\">${item.difficulty}</span><span>${item.domain}</span></div>\n      <p style=\"font-weight:600; font-size:14.5px;\">Question ${currentQ+1} of ${examQuestions.length}: ${item.q}</p>\n      <div class=\"quiz-opts\">${item.o.map((opt,oi)=>`<label class=\"quiz-opt ${examAnswers[currentQ]===oi?'selected-opt':''}\"><input type=\"radio\" name=\"examq\" value=\"${oi}\" ${examAnswers[currentQ]===oi?'checked':''}> ${opt}</label>`).join('')}</div>`;\n    area.querySelectorAll('input[name=\"examq\"]').forEach(inp=>{\n      inp.addEventListener('change', ()=>{ examAnswers[currentQ] = parseInt(inp.value); renderNavGrid(); });\n    });\n  }\n  document.getElementById('exam-prev-btn').addEventListener('click', ()=>{ if(currentQ>0){ currentQ--; renderQuestion(); renderNavGrid(); } });\n  document.getElementById('exam-next-btn').addEventListener('click', ()=>{ if(currentQ<examQuestions.length-1){ currentQ++; renderQuestion(); renderNavGrid(); } });\n  document.getElementById('exam-flag-btn').addEventListener('click', ()=>{ examFlags[currentQ] = !examFlags[currentQ]; renderNavGrid(); });\n  document.getElementById('exam-submit-btn').addEventListener('click', ()=>{ if(confirm('Submit the exam now?')) submitExam(); });\n\n  function submitExam(){\n    clearInterval(timerInterval);\n    let correct=0, wrong=0, skipped=0;\n    const perDomain = {};\n    examQuestions.forEach((item,i)=>{\n      if(!perDomain[item.domain]) perDomain[item.domain] = {correct:0,total:0};\n      perDomain[item.domain].total++;\n      if(examAnswers[i]===null){ skipped++; }\n      else if(examAnswers[i]===item.c){ correct++; perDomain[item.domain].correct++; }\n      else { wrong++; }\n      recordAnswer(item.domain, examAnswers[i]===item.c);\n    });\n    const rawScore = negativeMarking ? (correct - wrong*0.25) : correct;\n    const accuracy = examQuestions.length ? Math.round((correct/examQuestions.length)*100) : 0;\n    document.getElementById('exam-run-panel').style.display='none';\n    document.getElementById('exam-results-panel').style.display='block';\n    document.getElementById('exam-results-grid').innerHTML = `\n      <div class=\"metric-card\"><div class=\"m-label\">Correct</div><div class=\"m-val\" style=\"color:var(--green);\">${correct}</div></div>\n      <div class=\"metric-card\"><div class=\"m-label\">Wrong</div><div class=\"m-val\" style=\"color:var(--red-bright);\">${wrong}</div></div>\n      <div class=\"metric-card\"><div class=\"m-label\">Skipped</div><div class=\"m-val\" style=\"color:var(--amber);\">${skipped}</div></div>\n      <div class=\"metric-card\"><div class=\"m-label\">Accuracy</div><div class=\"m-val\">${accuracy}%</div></div>\n      <div class=\"metric-card\"><div class=\"m-label\">Score${negativeMarking?' (negative marking)':''}</div><div class=\"m-val\">${rawScore.toFixed(negativeMarking?2:0)}/${examQuestions.length}</div></div>`;\n    drawExamPerf(perDomain);\n    state.labsDone.add('mockexam');\n    updateBadge11();\n  }\n\n  function drawExamPerf(perDomain){\n    const canvas = document.getElementById('examPerfChart'); const ctx = canvas.getContext('2d');\n    const w = canvas.width = canvas.clientWidth||500, h = canvas.height=180;\n    ctx.clearRect(0,0,w,h);\n    const domains = Object.keys(perDomain);\n    const barW = (w-40)/domains.length - 10;\n    domains.forEach((d,i)=>{\n      const pct = perDomain[d].total ? perDomain[d].correct/perDomain[d].total : 0;\n      const x = 20 + i*((w-40)/domains.length);\n      const bh = pct*(h-50);\n      ctx.fillStyle = pct>=0.7 ? '#3ec28f' : pct>=0.4 ? '#e8a33d' : '#ff5a3c';\n      ctx.fillRect(x, h-30-bh, barW, bh);\n      ctx.fillStyle='#a7acb8'; ctx.font='9px sans-serif'; ctx.textAlign='center';\n      ctx.fillText(d.split(' ')[0], x+barW/2, h-14);\n      ctx.fillStyle='#eef0f3'; ctx.font='bold 10px sans-serif';\n      ctx.fillText(Math.round(pct*100)+'%', x+barW/2, h-34-bh);\n    });\n  }\n}\n\n;\n\n/* ---------- scenario labs ---------- */\nfunction initScenarioLabs(){\n  const grid = document.getElementById('scenario-lab-grid'); if(!grid) return;\n  const scenarios = [\n    {t:'Compromised Compute Instance', domain:'Security & Vault', scenario:'Cloud Guard flags unusual outbound traffic from web-vm-01 at 3am.', opts:['Ignore until business hours','Isolate the instance immediately (NSG/quarantine), then investigate','Delete the instance right away','Restart it and hope it clears'], c:1},\n    {t:'Broken VPN', domain:'Networking', scenario:'Site-to-Site VPN tunnel shows DOWN, on-prem team reports no connectivity.', opts:['Check the shared secret and CPE status first','Immediately delete and recreate the whole VCN','Assume it will recover on its own','Switch everything to FastConnect immediately'], c:0},\n    {t:'Failed Terraform Apply', domain:'Terraform', scenario:'terraform apply fails with a CIDR overlap error that wasn\\'t in the last plan.', opts:['Force apply with -auto-approve repeatedly','Run terraform plan/refresh to find the drift source first','Delete the state file','Ignore the error and retry blindly'], c:1},\n    {t:'Vault Key Rotation Failure', domain:'Security & Vault', scenario:'A scheduled key rotation failed to complete silently.', opts:['Check the key\\'s lifecycle state and IAM policy for the automation principal','Delete the key immediately','Assume rotation isn\\'t important','Disable the Vault entirely'], c:0},\n    {t:'Cloud Guard Alert', domain:'Security & Vault', scenario:'Cloud Guard reports a newly public Object Storage bucket.', opts:['Leave it, buckets are usually fine public','Remove public access immediately, then investigate who/what made the change','Delete the bucket entirely without investigation','Wait for the next audit cycle'], c:1},\n    {t:'Load Balancer Failure', domain:'Monitoring & Troubleshooting', scenario:'All backends show healthy, but customers report intermittent 502s.', opts:['Assume it\\'s a false alarm','Investigate backend crash-under-load behavior, not just health check status', 'Restart the load balancer only', 'Add more backends without investigating'], c:1},\n    {t:'DR Failover', domain:'HA/DR', scenario:'A real DR failover test to the replica region is being planned.', opts:['Skip the test, the plan is documented already','Execute the actual failover, validating app startup and data integrity end to end','Only test the network path, not the application','Assume replication guarantees success'], c:1},\n    {t:'Monitoring Alarm', domain:'Monitoring & Troubleshooting', scenario:'An alarm is firing correctly but nobody was paged.', opts:['Increase the alarm threshold','Check whether the notification topic subscription was ever confirmed', 'Delete the alarm', 'Assume the metric is wrong'], c:1},\n    {t:'Budget Overrun', domain:'Cost', scenario:'Production compartment hits 140% of its monthly budget.', opts:['Panic and shut down all production instances','Use Cost Analysis + Idle Resource Detector to find the spike source, then right-size', 'Ignore it until next month', 'Increase the budget without investigating'], c:1},\n    {t:'Audit Investigation', domain:'IAM & Governance', scenario:'A compliance audit needs proof of who accessed a specific secret last month.', opts:['Audit logs don\\'t retain that detail','Query the Audit service for API calls against that secret\\'s OCID', 'Ask each engineer individually', 'This information cannot be recovered'], c:1},\n  ];\n  grid.innerHTML = scenarios.map((s,i)=>`<div class=\"scenario-lab-card\" data-i=\"${i}\"><strong>${s.t}</strong></div>`).join('');\n  const detail = document.getElementById('scenario-lab-detail');\n  grid.querySelectorAll('.scenario-lab-card').forEach(card=>{\n    let openedAt = 0;\n    card.addEventListener('click', ()=>{\n      const s = scenarios[card.dataset.i];\n      openedAt = Date.now();\n      detail.style.display='block';\n      detail.innerHTML = `<p class=\"mono\" style=\"color:var(--red-bright);\">${s.scenario}</p>\n        <div class=\"quiz-opts mt-lg\">${s.opts.map((o,oi)=>`<label class=\"quiz-opt\"><input type=\"radio\" name=\"scenlab\" value=\"${oi}\"> ${o}</label>`).join('')}</div>\n        <div class=\"scenario-score-grid\" id=\"scenlab-scores\" style=\"display:none;\"></div>`;\n      detail.querySelectorAll('input[name=\"scenlab\"]').forEach((inp,oi)=>{\n        inp.addEventListener('change', ()=>{\n          const elapsed = ((Date.now()-openedAt)/1000).toFixed(1);\n          const correct = oi===s.c;\n          recordAnswer(s.domain, correct);\n          const speedScore = elapsed<8 ? 'Fast' : elapsed<20 ? 'Moderate' : 'Slow';\n          document.getElementById('scenlab-scores').style.display='grid';\n          document.getElementById('scenlab-scores').innerHTML = `\n            <div class=\"metric-card\"><div class=\"m-label\">Accuracy</div><div class=\"m-val\" style=\"color:${correct?'var(--green)':'var(--red-bright)'};\">${correct?'Correct':'Incorrect'}</div></div>\n            <div class=\"metric-card\"><div class=\"m-label\">Speed</div><div class=\"m-val\">${speedScore}</div></div>\n            <div class=\"metric-card\"><div class=\"m-label\">Decision Quality</div><div class=\"m-val\">${correct?'Sound':'Review needed'}</div></div>`;\n        });\n      });\n    });\n  });\n}\n\n/* ---------- interview preparation center ---------- */\nfunction initInterviewPrep(){\n  const wrap = document.getElementById('interview-list'); if(!wrap) return;\n  const questions = [\n    {cat:'fundamentals', q:'What is the difference between IaaS, PaaS, and SaaS?', ideal:'IaaS gives you raw infrastructure you manage yourself; PaaS manages the platform/runtime for you; SaaS is fully managed software you just use.', alt:'Frame it via responsibility: as you move IaaS\u2192PaaS\u2192SaaS, the provider takes on more of the stack.', mistakes:'Confusing where the line of responsibility actually sits for each model.', followup:'Which model would you choose for a legacy app needing OS-level access, and why?'},\n    {cat:'networking', q:'Explain the difference between a Security List and an NSG.', ideal:'Security Lists apply to an entire subnet; NSGs scope rules to specific VNICs, allowing finer-grained control without splitting into more subnets.', alt:'Use an analogy: Security Lists are a building\\'s front door policy; NSGs are per-office door policies.', mistakes:'Saying they\\'re interchangeable or that only one can be used at a time.', followup:'Can Security Lists and NSGs be used together on the same instance?'},\n    {cat:'security', q:'Walk me through OCI Vault\\'s envelope encryption model.', ideal:'A Master Encryption Key wraps a Data Encryption Key; the DEK does the actual bulk data encryption. The MEK itself never directly touches your data.', alt:'Compare to a safe (MEK) protecting a smaller key (DEK) that unlocks the actual filing cabinet (data).', mistakes:'Saying the MEK directly encrypts application data.', followup:'Why is this more efficient than using the MEK directly for everything?'},\n    {cat:'terraform', q:'What is Terraform state, and why does drift matter?', ideal:'State is Terraform\\'s record of what it believes exists. Drift happens when real infrastructure changes outside Terraform (e.g. manual Console edits), causing state to diverge from reality \u2014 which can cause failed or destructive applies.', alt:'Explain it as Terraform\\'s \"memory\" getting out of sync with reality.', mistakes:'Saying state doesn\\'t matter if you always use terraform apply.', followup:'How would you detect and resolve state drift safely?'},\n    {cat:'troubleshooting', q:'A production load balancer shows all backends healthy but customers report errors. How do you approach this?', ideal:'Apply structured troubleshooting: don\\'t trust health checks alone \u2014 they sample periodically. Check application logs for errors under real load, review recent deploys, and correlate error timing with traffic patterns.', alt:'Emphasize eliminating layers systematically rather than guessing.', mistakes:'Assuming healthy backends means the application layer is automatically fine.', followup:'What metrics would you add to catch this earlier next time?'},\n    {cat:'behavioral', q:'Tell me about a time you diagnosed a difficult production incident.', ideal:'Use the STAR method: Situation, Task, Action (methodology used), Result (resolution + what changed afterward to prevent recurrence).', alt:'Emphasize the postmortem/preventive action, not just the fix.', mistakes:'Only describing the fix, not the root cause analysis or prevention.', followup:'What would you do differently if it happened again?'},\n    {cat:'security', q:'How would you enforce least privilege in a growing engineering organization?', ideal:'Scope IAM policies to specific resource-families per compartment, use groups (not individuals), regularly audit unused permissions, and require justification for broad grants like \"manage all-resources.\"', alt:'Discuss periodic access reviews as an ongoing process, not a one-time setup.', mistakes:'Treating least privilege as a one-time configuration rather than an ongoing discipline.', followup:'How would you handle a legitimate but temporary need for elevated access?'},\n    {cat:'networking', q:'Explain the purpose of a NAT Gateway vs a Service Gateway.', ideal:'NAT Gateway gives private subnets outbound-only internet access; Service Gateway gives private access specifically to OCI public services without touching the internet at all.', alt:'Contrast \"internet, one-way\" (NAT) with \"OCI services, no internet\" (SGW).', mistakes:'Saying they serve the same purpose.', followup:'Which would you use for a private instance that only needs to reach Object Storage?'},\n    {cat:'terraform', q:'How do you structure Terraform for a multi-environment (dev/test/prod) setup?', ideal:'Use separate state files per environment (via workspaces or separate backends), parameterize with variables, and avoid sharing state across environments to prevent cross-environment blast radius.', alt:'Discuss module reuse with environment-specific variable files.', mistakes:'Using one shared state file across all environments.', followup:'How would you promote a change from dev to prod safely?'},\n    {cat:'troubleshooting', q:'How do you approach a \"no SSH access\" ticket?', ideal:'Work through the checklist systematically: SSH key, username, NSG, Security List, route table, public IP assignment, and cloud-init status \u2014 narrowing from network to host layer.', alt:'Frame it as OSI-layer-based elimination.', mistakes:'Jumping straight to \"reset the instance\" without diagnosis.', followup:'What would you check first if Serial Console also failed?'},\n    {cat:'fundamentals', q:'What are Availability Domains and Fault Domains, and why do both matter?', ideal:'ADs provide data-center-level isolation within a region; Fault Domains provide rack-level isolation within an AD. Both matter because different failure scales require different placement strategies.', alt:'Use a \"buildings vs floors\" analogy.', mistakes:'Treating them as interchangeable concepts.', followup:'How would you design a 3-tier app for maximum regional resilience?'},\n    {cat:'behavioral', q:'Describe a time you had to push back on a design decision for security or cost reasons.', ideal:'Focus on how you communicated the tradeoff with data (cost estimates, risk assessment) rather than just asserting an opinion, and how you reached agreement.', alt:'Emphasize collaboration and evidence over authority.', mistakes:'Framing it as \"I was right and they were wrong\" without nuance.', followup:'How did the outcome play out over time?'},\n    {cat:'security', q:'What is the difference between Cloud Guard and Security Zones?', ideal:'Cloud Guard is detective/responsive \u2014 it finds and can auto-remediate issues after they occur. Security Zones are preventive \u2014 they block non-compliant actions before they happen.', alt:'Frame it as \"after the fact\" vs \"before it happens.\"', mistakes:'Saying one replaces the need for the other.', followup:'Would you enable both on the same compartment? Why?'},\n    {cat:'networking', q:'How does longest-prefix-match work in route tables?', ideal:'When multiple route rules match a destination, the most specific (longest prefix / smallest CIDR range) rule is used, regardless of creation order.', alt:'Use a concrete example: a /24 wins over a /16 for a matching IP.', mistakes:'Assuming rule creation order determines priority.', followup:'How would you troubleshoot unexpected routing behavior?'},\n    {cat:'troubleshooting', q:'What is your process for a suspected DDoS or security incident on a production instance?', ideal:'Isolate first (quarantine/NSG lockdown) to stop the bleeding, preserve evidence (logs, console history) for investigation, then diagnose root cause before deciding on remediation and prevention.', alt:'Emphasize containment before deep investigation.', mistakes:'Deleting/rebuilding the instance immediately, destroying forensic evidence.', followup:'How would you balance speed of containment against evidence preservation?'},\n    {cat:'terraform', q:'What is OCI Resource Manager and how does it differ from running Terraform locally?', ideal:'Resource Manager is a managed service that runs Terraform stacks with managed state storage, drift detection, and a Console UI \u2014 reducing the need for local state file management.', alt:'Compare it to Terraform Cloud/Enterprise conceptually.', mistakes:'Saying it uses a different configuration language than open-source Terraform.', followup:'When might you still choose to run Terraform locally instead?'},\n    {cat:'behavioral', q:'How do you communicate a production incident to non-technical stakeholders?', ideal:'Lead with business impact (what\\'s affected, for whom, how badly), avoid jargon, give a clear next-update time, and follow up with a plain-language summary once resolved.', alt:'Emphasize cadence of updates over technical depth.', mistakes:'Leading with technical root cause details stakeholders can\\'t act on.', followup:'How would you handle a stakeholder demanding an ETA you don\\'t have yet?'},\n    {cat:'fundamentals', q:'Why would a company choose a multi-cloud strategy despite the added complexity?', ideal:'Risk diversification, avoiding vendor lock-in, and leveraging best-of-breed services per cloud \u2014 traded off against real operational overhead and skillset fragmentation.', alt:'Present it as a genuine tradeoff, not a strictly \"better\" choice.', mistakes:'Presenting multi-cloud as universally superior without acknowledging the cost.', followup:'How would you decide if multi-cloud is worth it for a given organization?'},\n  ];\n  const catBtns = document.querySelectorAll('#interview-cat-btns .chip-btn');\n  function render(cat){\n    const filtered = cat==='all' ? questions : questions.filter(q=>q.cat===cat);\n    wrap.innerHTML = filtered.map((item,i)=>`\n      <div class=\"interview-card\">\n        <div class=\"interview-q\" data-i=\"${i}\">Q: ${item.q}</div>\n        <div class=\"interview-a\" id=\"ia-${i}\">\n          <div class=\"ia-label\">Ideal Answer</div>${item.ideal}\n          <div class=\"ia-label\">Alternative Framing</div>${item.alt}\n          <div class=\"ia-label\">Common Mistakes</div>${item.mistakes}\n          <div class=\"ia-label\">Likely Follow-up</div>${item.followup}\n        </div>\n      </div>`).join('');\n    wrap.querySelectorAll('.interview-q').forEach(q=> q.addEventListener('click', ()=> document.getElementById('ia-'+q.dataset.i).classList.toggle('show')));\n  }\n  catBtns.forEach(b=> b.addEventListener('click', ()=>{ catBtns.forEach(x=>x.classList.remove('active')); b.classList.add('active'); render(b.dataset.icat); }));\n  render('all');\n}\n\n;\n\n/* ---------- doubt clearing center ---------- */\nfunction initDoubtClearing(){\n  const input = document.getElementById('doubt-search'); if(!input) return;\n  const kb = [\n    {topic:'NSG', keywords:['nsg','network security group'], explain:'A Network Security Group applies firewall rules to specific VNICs rather than an entire subnet \u2014 use it when different instances in the same subnet need different rules.', related:'Security Lists, VCN, VNIC', bp:'Combine with Security Lists for defense in depth; both apply simultaneously.'},\n    {topic:'Terraform State', keywords:['terraform state','state drift','tfstate'], explain:'Terraform state is its record of what infrastructure it believes exists. Drift occurs when reality diverges (e.g. manual Console changes), which can cause failed or unexpected applies.', related:'Resource Manager, drift detection', bp:'Never make manual changes to Terraform-managed resources; always run plan before apply.'},\n    {topic:'NotAuthorizedOrNotFound', keywords:['notauthorizedornotfound','401','403'], explain:'This error deliberately conflates \"doesn\\'t exist\" with \"you lack permission\" for security reasons. Always check the IAM policy first.', related:'IAM Policies, Dynamic Groups', bp:'Grant the minimum verb needed (inspect/read/use/manage) rather than defaulting to manage.'},\n    {topic:'RPO', keywords:['rpo','recovery point objective'], explain:'RPO is the maximum acceptable data loss, measured in time since the last good copy \u2014 it drives your backup/replication frequency requirements.', related:'RTO, DR, Backup', bp:'Set RPO based on business impact of data loss, then design backup frequency to meet it.'},\n    {topic:'RTO', keywords:['rto','recovery time objective'], explain:'RTO is the maximum acceptable downtime after a failure \u2014 it drives your failover automation and readiness requirements.', related:'RPO, DR, HA', bp:'A low RTO usually requires pre-provisioned standby capacity, not just backups.'},\n    {topic:'Envelope Encryption', keywords:['envelope encryption','mek','dek'], explain:'A Master Encryption Key wraps a Data Encryption Key; the DEK does the actual bulk data encryption. This is how OCI Vault protects data efficiently at scale.', related:'Vault, KMS, HSM', bp:'Never assume the MEK directly touches your data \u2014 it only ever wraps/unwraps DEKs.'},\n    {topic:'Longest Prefix Match', keywords:['longest prefix match','route table','lpm'], explain:'When multiple route rules match a destination, OCI uses the most specific (longest prefix) rule, regardless of which was created first.', related:'Route Tables, Gateways', bp:'When troubleshooting unexpected routing, always check for a more specific competing rule.'},\n    {topic:'Cloud Guard vs Security Zones', keywords:['cloud guard','security zones'], explain:'Cloud Guard detects and responds after a misconfiguration occurs. Security Zones block non-compliant actions before they happen. They are complementary, not redundant.', related:'IAM, Compliance', bp:'Use Security Zones on your most sensitive compartments as a hard guardrail.'},\n    {topic:'Least Privilege', keywords:['least privilege','rbac'], explain:'Grant only the exact permissions a principal needs, scoped to the smallest resource-family and compartment necessary \u2014 nothing more.', related:'IAM Policies, Groups', bp:'Periodically audit for unused broad grants like \"manage all-resources.\"'},\n    {topic:'chmod 777', keywords:['chmod 777','chmod'], explain:'chmod 777 makes a file world-writable \u2014 any local user or any process that achieves code execution can modify it. Almost never the correct fix for a permission error.', related:'Linux Permissions, Security', bp:'Diagnose the actual owner/group mismatch instead of defaulting to 777.'},\n    {topic:'Service Gateway', keywords:['service gateway','sgw'], explain:'Service Gateway lets a private subnet reach OCI public services (like Object Storage) without traversing the internet at all.', related:'NAT Gateway, VCN', bp:'Prefer SGW over NAT Gateway when the destination is an OCI service, for a smaller attack surface.'},\n    {topic:'Instance Metadata', keywords:['instance metadata','169.254.169.254'], explain:'Every OCI instance can query http://169.254.169.254/latest/meta-data/ for instance-id, VNIC info, and other launch-time metadata \u2014 no credentials embedded.', related:'Cloud-init, Instance Principals', bp:'Use instance metadata for self-configuring startup scripts rather than hardcoding values.'},\n    {topic:'MQL', keywords:['mql','metric query language'], explain:'Metric Query Language is the syntax used to query and aggregate OCI Monitoring metrics, powering both dashboards and alarms.', related:'Monitoring, Alarms', bp:'Alarm on symptoms your customers actually feel, not just raw resource metrics.'},\n    {topic:'Service Connector Hub', keywords:['service connector hub','sch'], explain:'Service Connector Hub routes logs/metrics from a source OCI service to a target (Streaming, Object Storage, Functions, another region) without custom glue code.', related:'Logging, Monitoring', bp:'Use it to centralize multi-service logs instead of building custom export scripts.'},\n    {topic:'Bastion', keywords:['bastion'], explain:'OCI Bastion provides short-lived, brokered SSH access to private instances \u2014 no permanent jump box, no public IP needed on the target.', related:'SSH, Private Subnets', bp:'Prefer Bastion over direct public SSH exposure for any private-subnet access.'},\n    {topic:'Idle Resources', keywords:['idle resource','unused volume','stopped instance'], explain:'Stopped instances, unattached volumes, unused load balancers, and reserved-but-unassigned IPs are pure waste \u2014 the fastest, lowest-risk cost optimization.', related:'Cost Analysis, FinOps', bp:'Run an idle-resource sweep monthly as part of a FinOps review.'},\n    {topic:'Compartment vs Tag', keywords:['compartment','tag','tagging'], explain:'A Compartment is an access-control and isolation boundary. A Tag is a classification label for cost/governance reporting \u2014 they solve different problems.', related:'IAM, Governance', bp:'Design compartments around one dominant axis (env or team); use tags for cross-cutting classification like cost center.'},\n    {topic:'Quota vs Limit', keywords:['quota','service limit'], explain:'A Quota is a self-imposed cap set by tenancy admins. A Service Limit is a provider ceiling that requires a support request to raise.', related:'Governance, Compute', bp:'Use Quotas to prevent runaway resource sprawl within existing Limits.'},\n    {topic:'oci iam policy syntax', keywords:['policy syntax','allow group'], explain:'OCI policies follow: Allow <subject> to <verb> <resource-type> in <location> [where <condition>]. Verbs, in increasing power: inspect, read, use, manage.', related:'IAM, RBAC', bp:'Default to the narrowest verb that satisfies the requirement.'},\n    {topic:'Asymmetric Routing', keywords:['asymmetric routing'], explain:'Occurs when outbound and return traffic take different paths through different firewalls. A stateful firewall only sees one direction and drops the \"unrecognized\" return traffic.', related:'Firewalls, Route Tables', bp:'Ensure both directions of a flow traverse the same firewall/path.'},\n  ];\n  function render(query){\n    const wrap = document.getElementById('doubt-results');\n    if(!query){ wrap.innerHTML = '<p class=\"small\">Start typing to search across every topic covered in this course.</p>'; return; }\n    const q = query.toLowerCase();\n    const matches = kb.filter(item=> item.topic.toLowerCase().includes(q) || item.keywords.some(k=>k.includes(q)));\n    wrap.innerHTML = matches.length ? matches.map(item=>`\n      <div class=\"doubt-result-card\">\n        <h4 style=\"margin-bottom:8px;\">${item.topic}</h4>\n        <p style=\"font-size:13px; color:var(--text-2);\">${item.explain}</p>\n        <p class=\"small mt-lg\"><strong>Related:</strong> ${item.related}</p>\n        <p class=\"small\"><strong>Best practice:</strong> ${item.bp}</p>\n      </div>`).join('') : '<p class=\"small\">No matches \u2014 try a shorter or different keyword.</p>';\n  }\n  input.addEventListener('input', ()=> render(input.value.trim()));\n  render('');\n}\n\n;\n\n/* ---------- final revision center ---------- */\nfunction initFinalRevision(){\n  const btns = document.querySelectorAll('#finalrev-tabs .chip-btn'); if(!btns.length) return;\n  const content = {\n    iam: `<h4>IAM &amp; Governance</h4><ul style=\"margin-left:18px;\"><li>Verbs: inspect &lt; read &lt; use &lt; manage</li><li>Policies inherit down from parent compartments</li><li>Root compartment = the tenancy itself</li><li>Compartment = access boundary; Tag = classification</li><li>Quota = self-imposed; Limit = provider ceiling</li><li>Organization Management links billing, not IAM</li></ul>`,\n    networking: `<h4>Networking</h4><ul style=\"margin-left:18px;\"><li>VCN CIDR: /16 to /30</li><li>Route tables use longest-prefix-match</li><li>IGW = public in/out; NAT = private out-only; SGW = private to OCI services</li><li>Security Lists = subnet-wide; NSGs = per-VNIC</li><li>LPG = same-region peering; DRG = cross-region / on-prem</li></ul>`,\n    compute: `<h4>Compute &amp; Storage</h4><ul style=\"margin-left:18px;\"><li>cloud-init runs once, on first boot</li><li>Block volumes attach only within the same AD</li><li>Object = HTTP scale; Block = attached; File = shared NFS; Archive = cheapest/slowest</li><li>Right-size on real utilization, not guesses</li></ul>`,\n    terraform: `<h4>Terraform</h4><ul style=\"margin-left:18px;\"><li>State = Terraform's record of reality</li><li>Drift = manual changes outside Terraform</li><li>Always plan before apply</li><li>Resource Manager = managed Terraform + state + drift detection</li></ul>`,\n    security: `<h4>Security &amp; Vault</h4><ul style=\"margin-left:18px;\"><li>Envelope encryption: MEK wraps DEK; DEK encrypts data</li><li>HSM Protected = FIPS 140-2 Level 3 hardware-backed</li><li>Scheduled key deletion has a mandatory 7-30 day wait</li><li>Cloud Guard = detect+respond; Security Zones = block</li></ul>`,\n    hadr: `<h4>HA/DR</h4><ul style=\"margin-left:18px;\"><li>RPO = acceptable data loss (time); RTO = acceptable downtime</li><li>Spread across Fault Domains at minimum for HA</li><li>Only a real, executed failover test validates DR</li><li>Cross-region Vault replication protects against regional failure</li></ul>`,\n    monitoring: `<h4>Monitoring &amp; Logging</h4><ul style=\"margin-left:18px;\"><li>MQL powers Monitoring metrics/alarms</li><li>Alarms need a confirmed notification subscription to actually page someone</li><li>Service Connector Hub routes logs/metrics between services</li><li>Audit logging is automatic tenancy-wide</li></ul>`,\n    cli: `<h4>CLI Quick Reference</h4><p class=\"mono\" style=\"color:var(--blue); line-height:2;\">oci iam policy list<br>oci network vcn list<br>oci compute instance list<br>oci bv volume list<br>oci os bucket create<br>oci kms management key list<br>oci vault secret list<br>oci logging log list</p>`\n  };\n  function render(key){ document.getElementById('finalrev-content').innerHTML = content[key]; }\n  btns.forEach(b=> b.addEventListener('click', ()=>{ btns.forEach(x=>x.classList.remove('active')); b.classList.add('active'); render(b.dataset.frtab); }));\n  render('iam');\n}\n\n/* ---------- flashcards 11 ---------- */\nfunction initFlashcards11(){\n  const wrap = document.getElementById('flash-wrap11'); if(!wrap) return;\n  const cards = [\n    ['Policy verb order','inspect < read < use < manage'],\n    ['Longest prefix match','The most specific matching route rule always wins'],\n    ['Envelope encryption','MEK wraps DEK; DEK encrypts the actual data'],\n    ['RPO vs RTO','RPO = data loss tolerance; RTO = downtime tolerance'],\n    ['Cloud Guard vs Security Zones','Detect+respond vs hard-block, complementary'],\n    ['Terraform drift','Reality diverges from Terraform state, usually via manual changes'],\n    ['Security List vs NSG','Subnet-wide vs per-VNIC scope'],\n    ['IGW vs NAT vs SGW','Public in/out vs private out-only vs private-to-OCI-services'],\n    ['DR test validity','Only a real, executed failover counts'],\n    ['Least privilege','Grant only the exact permission needed, nothing more'],\n    ['Idle resources','The fastest, lowest-risk cost optimization'],\n    ['Postmortem essentials','Root cause + corrective AND preventive action'],\n  ];\n  wrap.innerHTML = cards.map(([f,b])=>`<div class=\"flashcard\"><div class=\"fc-inner\"><div class=\"fc-face fc-front\">${f}</div><div class=\"fc-face fc-back\">${b}</div></div></div>`).join('');\n  wrap.querySelectorAll('.flashcard').forEach(fc=> fc.addEventListener('click', ()=> fc.classList.toggle('flipped')));\n}\n\n/* ---------- final certification challenge (20 mixed questions) ---------- */\nfunction initQuiz11(){\n  const wrap = document.getElementById('quiz-wrap11'); if(!wrap) return;\n  function shuffle(arr){ const a=[...arr]; for(let i=a.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); [a[i],a[j]]=[a[j],a[i]]; } return a; }\n  const Q = shuffle(QBANK).slice(0,20);\n  state.quizTotal = Q.length;\n  wrap.innerHTML = Q.map((item,qi)=>`\n    <div class=\"quiz-q\" id=\"quiz11-${qi}\">\n      <div class=\"qtext\"><span class=\"tag\" style=\"margin-right:8px;\">${item.domain}</span>${qi+1}. ${item.q}</div>\n      <div class=\"quiz-opts\">${item.o.map((opt,oi)=>`<label class=\"quiz-opt\"><input type=\"radio\" name=\"q11-${qi}\" value=\"${oi}\"> ${opt}</label>`).join('')}</div>\n      <div class=\"quiz-explain\">${item.e}</div>\n    </div>`).join('');\n  wrap.querySelectorAll('.quiz-q').forEach((qEl, qi)=>{\n    qEl.addEventListener('change', e=>{\n      if(qEl.classList.contains('answered')) return;\n      qEl.classList.add('answered');\n      const chosen = parseInt(e.target.value);\n      qEl.querySelectorAll('.quiz-opt').forEach((o,oi)=>{ if(oi===Q[qi].c) o.classList.add('correct'); else if(oi===chosen) o.classList.add('incorrect'); });\n      state.quizAnswered++; if(chosen===Q[qi].c) state.quizScore++;\n      recordAnswer(Q[qi].domain, chosen===Q[qi].c);\n      document.getElementById('score-chip-val').textContent = `${state.quizScore} / ${state.quizAnswered}`;\n      document.getElementById('quiz-final-score11').textContent = `${state.quizScore} / ${Q.length}`;\n      document.getElementById('cert-score-display11').textContent = `${state.quizScore}/${Q.length}`;\n      updateBadge11();\n    });\n  });\n}\n\n/* ---------- badge / certificate 11 ---------- */\nfunction updateBadge11(){\n  const scrollPct = window.__lastScrollPct11 || 0;\n  const quizPct = state.quizTotal ? (state.quizAnswered/state.quizTotal)*100 : 0;\n  const combined = Math.round(scrollPct*0.5 + quizPct*0.5);\n  const circle = document.getElementById('badge-circle11'); if(!circle) return;\n  circle.style.setProperty('--pct', (combined*3.6)+'deg');\n  document.getElementById('badge-pct11').textContent = combined+'%';\n  const title = document.getElementById('badge-title11'); const sub = document.getElementById('badge-sub11');\n  if(combined>=95){ title.textContent='\ud83c\udfc6 Course Complete'; sub.textContent='Certificate preview unlocked \u2014 congratulations on finishing the full 11-day program.'; }\n  else if(combined>=50){ title.textContent='\ud83d\udfe0 Halfway there'; sub.textContent='Keep going through the remaining sections and the Final Certification Challenge.'; }\n  else { title.textContent='Keep going'; sub.textContent='Complete every section and the Final Certification Challenge to preview your certificate.'; }\n  const d = new Date(); document.getElementById('cert-date-display11').textContent = d.toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'});\n}\n"};
